import 'package:synapse_bridge/synapse_bridge.dart';
import 'package:synapse/core/domain/repositories/plugin_repository.dart';

/// Service that generates plugin registry information for LLM prompts.
/// 
/// This service reads installed and enabled plugins and formats them
/// into a string that can be injected into LLM system prompts.
class PluginRegistryService {
  final PluginRepository _pluginRepository;

  PluginRegistryService(this._pluginRepository);

  /// Generate the PLUGIN REGISTRY section for LLM prompts.
  /// 
  /// Returns a formatted string listing all enabled plugins with their
  /// triggers and required payload schemas.
  Future<String> generateLLMRegistry() async {
    final plugins = await _pluginRepository.getEnabledPlugins();

    if (plugins.isEmpty) {
      return _getDefaultRegistry();
    }

    final buffer = StringBuffer();

    for (final plugin in plugins) {
      buffer.writeln('- ID: "${plugin.id}"');
      buffer.writeln('  - Triggers (action_type values): ${_formatTriggers(plugin.triggers)}');
      buffer.writeln('  - Payload Schema: ${_formatInputSchema(plugin.inputSchema)}');
      buffer.writeln();
    }

    return buffer.toString().trimRight();
  }

  /// Get list of enabled plugin IDs for quick lookup
  Future<List<String>> getEnabledPluginIds() async {
    final plugins = await _pluginRepository.getEnabledPlugins();
    return plugins.map((p) => p.id).toList();
  }

  /// Check if a specific plugin is available and enabled
  Future<bool> isPluginAvailable(String pluginId) async {
    final ids = await getEnabledPluginIds();
    return ids.contains(pluginId);
  }

  /// Get plugin by ID if it's enabled
  Future<SynapsePlugin?> getEnabledPlugin(String pluginId) async {
    final plugins = await _pluginRepository.getEnabledPlugins();
    try {
      return plugins.firstWhere((p) => p.id == pluginId);
    } catch (_) {
      return null;
    }
  }

  String _formatTriggers(List<String> triggers) {
    if (triggers.isEmpty) {
      return 'General purpose';
    }
    return triggers.join(', ');
  }

  String _formatInputSchema(Map<String, dynamic> schema) {
    if (schema.isEmpty) {
      return '{}';
    }

    final properties = schema['properties'] as Map<String, dynamic>?;
    if (properties == null || properties.isEmpty) {
      return '{}';
    }

    final fields = <String>[];
    properties.forEach((key, value) {
      final type = _jsonSchemaTypeToString(value as Map<String, dynamic>);
      fields.add('"$key": $type');
    });

    return '{ ${fields.join(', ')} }';
  }

  String _jsonSchemaTypeToString(Map<String, dynamic> schema) {
    final type = schema['type'] as String?;
    final enumValues = schema['enum'] as List<dynamic>?;

    if (enumValues != null) {
      return enumValues.map((e) => '"$e"').join('|');
    }

    switch (type) {
      case 'string':
        return 'string';
      case 'number':
      case 'integer':
        return 'number';
      case 'boolean':
        return 'boolean';
      case 'array':
        final items = schema['items'] as Map<String, dynamic>?;
        if (items != null) {
          return '${_jsonSchemaTypeToString(items)}[]';
        }
        return 'array';
      case 'object':
        return 'object';
      default:
        return 'any';
    }
  }

  /// Default registry when no plugins are installed
  String _getDefaultRegistry() {
    return '''
- ID: "com.synapse.note"
  - Trigger: General info, notes, text, snippets
  - Required Payload: { "title": string, "body": string, "tags": string[] }
'''.trimRight();
  }
}

