import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:http/http.dart' as http;
import 'package:synapse/data/models/plugin_store_dtos.dart';
import 'package:synapse/services/logger/logger_service.dart';


abstract class PluginStoreRemoteDataSource {

  Future<List<PluginListItemDto>> fetchPlugins({String? category, String? query});


  Future<PluginDetailDto> fetchPluginDetail(String packageId);

  Future<Uint8List> downloadSynxPackage(String downloadUrl);
}

/// Implementation of [PluginStoreRemoteDataSource]
class PluginStoreRemoteDataSourceImpl implements PluginStoreRemoteDataSource {
  final http.Client _client;
  final String _baseUrl;

  PluginStoreRemoteDataSourceImpl({
    http.Client? client,
    String? baseUrl,
  })  : _client = client ?? http.Client(),
        _baseUrl = "${dotenv.get("SYNAPSE_MARKETPLACE")}api/v1" ?? 'https://api.synapse.app/v1';

  @override
  Future<List<PluginListItemDto>> fetchPlugins({String? category, String? query}) async {
    try {
      final queryParams = <String, String>{};
      if (category != null) queryParams['category'] = category;
      if (query != null) queryParams['q'] = query;

      final uri = Uri.parse('$_baseUrl/store/plugins?pageSize=20&page=0').replace(queryParameters: queryParams.isNotEmpty ? queryParams : null);

      LoggerService.info('PluginStoreRemoteDataSource: Fetching plugins from $uri');

      final response = await _client.get(uri);

      if (response.statusCode != 200) {
        throw PluginStoreApiException(
          'Failed to fetch plugins',
          statusCode: response.statusCode,
          body: response.body,
        );
      }

      final List<dynamic> jsonList = jsonDecode(response.body)["data"] as List<dynamic>? ?? [];

      final responseList = jsonList
          .map<PluginListItemDto>((item) => PluginListItemDto.fromJson(item as Map<String, dynamic>))
          .toList();

      return responseList;
    } catch (e) {
      LoggerService.error('PluginStoreRemoteDataSource: Error fetching plugins', e);
      rethrow;
    }
  }

  @override
  Future<PluginDetailDto> fetchPluginDetail(String packageId) async {
    try {
      final uri = Uri.parse('$_baseUrl/store/plugins/$packageId');

      LoggerService.info('PluginStoreRemoteDataSource: Fetching plugin detail for $packageId');

      final response = await _client.get(uri);

      if (response.statusCode != 200) {
        throw PluginStoreApiException(
          'Failed to fetch plugin detail',
          statusCode: response.statusCode,
          body: response.body,
        );
      }

      final json = jsonDecode(response.body) as Map<String, dynamic>;
      return PluginDetailDto.fromJson(json);
    } catch (e) {
      LoggerService.error('PluginStoreRemoteDataSource: Error fetching plugin detail', e);
      rethrow;
    }
  }

  @override
  Future<Uint8List> downloadSynxPackage(String downloadUrl) async {
    try {
      LoggerService.info('PluginStoreRemoteDataSource: Downloading .synx from $downloadUrl');

      final uri = Uri.parse(downloadUrl);
      final response = await _client.get(uri);

      if (response.statusCode != 200) {
        throw PluginStoreApiException(
          'Failed to download .synx package',
          statusCode: response.statusCode,
          body: response.body,
        );
      }

      LoggerService.info('PluginStoreRemoteDataSource: Downloaded ${response.bodyBytes.length} bytes');
      return Uint8List.fromList(response.bodyBytes);
    } catch (e) {
      LoggerService.error('PluginStoreRemoteDataSource: Error downloading package', e);
      rethrow;
    }
  }
}

/// Exception thrown when the Plugin Store API returns an error.
class PluginStoreApiException implements Exception {
  final String message;
  final int? statusCode;
  final String? body;

  PluginStoreApiException(this.message, {this.statusCode, this.body});

  @override
  String toString() {
    if (statusCode != null) {
      return 'PluginStoreApiException: $message (HTTP $statusCode)';
    }
    return 'PluginStoreApiException: $message';
  }
}

