//These map to marketplace api response
class PluginListItemDto {
  final String id;
  final String packageId;
  final String name;
  final String description;
  final String author;
  final String? iconKey;
  final String status;
  final String? latestVersionId;
  final String? category;
  final String? tags;
  final String? sourceUrl;
  final DateTime createdAt;
  final DateTime updatedAt;

  PluginListItemDto({
    required this.id,
    required this.packageId,
    required this.name,
    required this.description,
    required this.author,
    this.iconKey,
    required this.status,
    this.latestVersionId,
    this.category,
    this.tags,
    this.sourceUrl,
    required this.createdAt,
    required this.updatedAt,
  });

  factory PluginListItemDto.fromJson(Map<String, dynamic> json) {
    return PluginListItemDto(
      id: json['id'] as String,
      packageId: json['packageId'] as String,
      name: json['name'] as String,
      description: json['description'] as String? ?? '',
      author: json['author'] as String? ?? '',
      iconKey: json['iconKey'] as String?,
      status: json['status'] as String,
      latestVersionId: json['latestVersionId'] as String?,
      category: json['category'] as String?,
      tags: json['tags'] as String?,
      sourceUrl: json['sourceUrl'] as String?,
      createdAt: DateTime.parse(json['createdAt'] as String),
      updatedAt: DateTime.parse(json['updatedAt'] as String),
    );
  }

  List<String> get tagList => tags?.split(',').map((t) => t.trim()).toList() ?? [];
}

/// Full plugin details for download/installation
class PluginDetailDto {
  // Plugin metadata
  final String id;
  final String packageId;
  final String name;
  final String description;
  final String author;
  final String? iconKey;
  final String status;
  final String? category;
  final String? tags;
  final String? sourceUrl;
  final DateTime pluginCreatedAt;

  // Version details
  final String versionId;
  final String version;
  final Map<String, dynamic> manifest;
  final String? minAppVersion;
  final String? releaseNotes;
  final DateTime versionCreatedAt;
  final int downloadCount;

  // Download information (Supabase Storage)
  final String downloadUrl;
  final int expiresAt;
  final int fileSizeBytes;
  final String checksumSha256;
  final String storageBucket;
  final String storagePath;

  PluginDetailDto({
    required this.id,
    required this.packageId,
    required this.name,
    required this.description,
    required this.author,
    this.iconKey,
    required this.status,
    this.category,
    this.tags,
    this.sourceUrl,
    required this.pluginCreatedAt,
    required this.versionId,
    required this.version,
    required this.manifest,
    this.minAppVersion,
    this.releaseNotes,
    required this.versionCreatedAt,
    required this.downloadCount,
    required this.downloadUrl,
    required this.expiresAt,
    required this.fileSizeBytes,
    required this.checksumSha256,
    required this.storageBucket,
    required this.storagePath,
  });

  factory PluginDetailDto.fromJson(Map<String, dynamic> json) {
    return PluginDetailDto(
      id: json['id'] as String,
      packageId: json['packageId'] as String,
      name: json['name'] as String,
      description: json['description'] as String? ?? '',
      author: json['author'] as String? ?? '',
      iconKey: json['iconKey'] as String?,
      status: json['status'] as String,
      category: json['category'] as String?,
      tags: json['tags'] as String?,
      sourceUrl: json['sourceUrl'] as String?,
      pluginCreatedAt: DateTime.parse(json['pluginCreatedAt'] as String),
      versionId: json['versionId'] as String,
      version: json['version'] as String,
      manifest: json['manifest'] as Map<String, dynamic>? ?? {},
      minAppVersion: json['minAppVersion'] as String?,
      releaseNotes: json['releaseNotes'] as String?,
      versionCreatedAt: DateTime.parse(json['versionCreatedAt'] as String),
      downloadCount: (json['downloadCount'] as num?)?.toInt() ?? 0,
      downloadUrl: json['downloadUrl'] as String,
      expiresAt: (json['expiresAt'] as num).toInt(),
      fileSizeBytes: (json['fileSizeBytes'] as num).toInt(),
      checksumSha256: json['checksumSha256'] as String,
      storageBucket: json['storageBucket'] as String,
      storagePath: json['storagePath'] as String,
    );
  }

  /// Check if the download URL has expired
  bool get isExpired => DateTime.now().millisecondsSinceEpoch ~/ 1000 > expiresAt;

  /// Human-readable file size
  String get formattedSize {
    if (fileSizeBytes < 1024) return '$fileSizeBytes B';
    if (fileSizeBytes < 1024 * 1024) return '${(fileSizeBytes / 1024).toStringAsFixed(1)} KB';
    return '${(fileSizeBytes / (1024 * 1024)).toStringAsFixed(1)} MB';
  }
}

