import 'dart:typed_data';

import 'package:crypto/crypto.dart';
import 'package:synapse_bridge/synapse_bridge.dart';
import 'package:synapse/core/domain/repositories/plugin_repository.dart';
import 'package:synapse/core/domain/repositories/plugin_store_repository.dart';
import 'package:synapse/data/data_sources/remote/plugin_store_remote_data_source.dart';
import 'package:synapse/data/models/plugin_store_dtos.dart';
import 'package:synapse/services/logger/logger_service.dart';

/// Implementation of [PluginStoreRepository].
///
/// Handles browsing the marketplace and installing plugins with
/// integrity verification.
class PluginStoreRepositoryImpl implements PluginStoreRepository {
  final PluginStoreRemoteDataSource _remoteDataSource;
  final PluginRepository _pluginRepository;

  PluginStoreRepositoryImpl({
    required PluginStoreRemoteDataSource remoteDataSource,
    required PluginRepository pluginRepository,
  }) : _remoteDataSource = remoteDataSource,
       _pluginRepository = pluginRepository;

  @override
  Future<List<PluginListItemDto>> browsePlugins({
    String? category,
    String? query,
  }) async {
    return _remoteDataSource.fetchPlugins(category: category, query: query);
  }

  @override
  Future<PluginDetailDto> getPluginDetail(String packageId) async {
    return _remoteDataSource.fetchPluginDetail(packageId);
  }

  @override
  Future<SynapsePlugin> installPlugin(String packageId) async {
    LoggerService.info('PluginStoreRepository: Installing plugin $packageId');

