import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:archive/archive.dart';
import 'package:crypto/crypto.dart';

import 'logger.dart';
import 'plugin_entity.dart';

/// Represents a Synapse Plugin Package (.synx)
///
/// A .synx file is a ZIP archive containing:
/// - manifest.json (required)
/// - plugin.js (required)
/// - icon.png (optional)
/// - README.md (optional)
class SynxPackage {
  final int manifestVersion = 2;
  final String id;
  final String name;
  final String version;
  final String description;
  final String author;
  final String? authorUrl;
  final String? homepage;
  final String? license;
  final String? minSynapseVersion;

  final SynxSecurity security;
  final List<PluginConnectionConfig> connections;
  final List<PluginActionConfig> actions;

  List<String> get triggers =>
      actions.expand((action) => action.triggers).toSet().toList();
  Map<String, dynamic> get inputSchema =>
      actions.isEmpty ? const {} : actions.first.inputSchema;
  final List<String> categories;
  final List<String> keywords;

  final String script;
  final Uint8List? iconData;
  final String? readme;

  SynxPackage({
    required this.id,
    required this.name,
    required this.version,
    this.description = '',
    this.author = '',
    this.authorUrl,
    this.homepage,
    this.license,
    this.minSynapseVersion,
    required this.security,
    this.connections = const [],
    this.actions = const [],
    this.categories = const [],
    this.keywords = const [],
    required this.script,
    this.iconData,
    this.readme,
  });

  /// Read a .synx package from file path
  static Future<SynxPackage> fromFile(String filePath) async {
    final file = File(filePath);
    if (!await file.exists()) {
      throw SynxPackageException('File not found: $filePath');
    }

    final bytes = await file.readAsBytes();
    return fromBytes(bytes);
  }

  /// Read a .synx package from bytes (for network downloads)
  static SynxPackage fromBytes(Uint8List bytes) {
    final archive = ZipDecoder().decodeBytes(bytes);

    // Find required files
    final manifestFile = archive.findFile('manifest.json');
    final scriptFile = archive.findFile('plugin.js');

    if (manifestFile == null) {
      throw SynxPackageException('manifest.json not found in package');
    }
    if (scriptFile == null) {
      throw SynxPackageException('plugin.js not found in package');
    }

    // Parse manifest
    final manifestJson =
        jsonDecode(utf8.decode(manifestFile.content as List<int>))
            as Map<String, dynamic>;
    try {
      validateManifestV2Contract(manifestJson);
    } on FormatException catch (error) {
      throw SynxPackageException(error.message.toString());
    }

    // Get script content
    final script = utf8.decode(scriptFile.content as List<int>);

    // Validate content hash if present
    final securityJson =
        manifestJson['security'] as Map<String, dynamic>? ?? {};
    final declaredHash = securityJson['contentHash'] as String?;
    if (declaredHash != null) {
      final actualHash = 'sha256-${sha256.convert(utf8.encode(script))}';
      if (actualHash != declaredHash) {
        throw SynxPackageException(
            'Content hash mismatch! Expected $declaredHash, got $actualHash');
      }
    }

    // Optional files
    final iconFile = archive.findFile('icon.png');
    final readmeFile = archive.findFile('README.md');

    return SynxPackage(
      id: manifestJson['id'] as String,
      name: manifestJson['name'] as String,
      version: manifestJson['version'] as String? ?? '1.0.0',
      description: manifestJson['description'] as String? ?? '',
      author: manifestJson['author'] as String? ?? '',
      authorUrl: manifestJson['authorUrl'] as String?,
      homepage: manifestJson['homepage'] as String?,
      license: manifestJson['license'] as String?,
      minSynapseVersion: manifestJson['minSynapseVersion'] as String?,
      security: SynxSecurity(
        allowedDomains: List<String>.from(securityJson['allowedDomains'] ?? []),
        permissions:
            List<String>.from(securityJson['permissions'] ?? ['network']),
        contentHash: declaredHash,
        allowedApps: List<String>.from(securityJson['allowedApps'] ?? []),
      ),
      connections: (manifestJson['connections'] as List<dynamic>? ?? const [])
          .map(
            (item) => PluginConnectionConfig.fromJson(
              Map<String, dynamic>.from(item as Map),
            ),
          )
          .toList(),
      actions: (manifestJson['actions'] as List<dynamic>? ?? const [])
          .map(
            (item) => PluginActionConfig.fromJson(
              Map<String, dynamic>.from(item as Map),
            ),
          )
          .toList(),
      categories: List<String>.from(manifestJson['categories'] ?? []),
      keywords: List<String>.from(manifestJson['keywords'] ?? []),
      script: script,
      iconData: iconFile != null
          ? Uint8List.fromList(iconFile.content as List<int>)
          : null,
      readme: readmeFile != null
          ? utf8.decode(readmeFile.content as List<int>)
          : null,
    );
  }

  /// Create a .synx package from this object
  Uint8List toBytes() {
    final archive = Archive();

    // Create manifest with content hash
    final contentHash = 'sha256-${sha256.convert(utf8.encode(script))}';
    final manifest = _manifestJson(contentHash: contentHash);

    final manifestBytes =
        utf8.encode(const JsonEncoder.withIndent('  ').convert(manifest));
    archive.addFile(
        ArchiveFile('manifest.json', manifestBytes.length, manifestBytes));

    // Add script
    final scriptBytes = utf8.encode(script);
    archive.addFile(ArchiveFile('plugin.js', scriptBytes.length, scriptBytes));

    // Add icon if present
    if (iconData != null) {
      archive.addFile(ArchiveFile('icon.png', iconData!.length, iconData!));
    }

    // Add readme if present
    if (readme != null) {
      final readmeBytes = utf8.encode(readme!);
      archive
          .addFile(ArchiveFile('README.md', readmeBytes.length, readmeBytes));
    }

    final zipped = ZipEncoder().encode(archive);
    return Uint8List.fromList(zipped);
  }

  /// Save the package to a file
  Future<File> saveToFile(String directory, {String? filename}) async {
    final name = filename ?? '$id-$version.synx';
    final file = File('$directory/$name');
    await file.writeAsBytes(toBytes());
    return file;
  }

  /// Extract the package to a directory (for installation)
  Future<void> extractTo(String targetDir) async {
    final dir = Directory(targetDir);
    if (!await dir.exists()) {
      await dir.create(recursive: true);
    }

    // Write manifest
    final manifestFile = File('${dir.path}/manifest.json');
    await manifestFile.writeAsString(
      jsonEncode(_manifestJson(contentHash: security.contentHash)),
    );

    // Write script
    final scriptFile = File('${dir.path}/plugin.js');
    await scriptFile.writeAsString(script);

    // Write icon if present
    if (iconData != null) {
      final iconFile = File('${dir.path}/icon.png');
      await iconFile.writeAsBytes(iconData!);
    }

    // Write readme if present
    if (readme != null) {
      final readmeFile = File('${dir.path}/README.md');
      await readmeFile.writeAsString(readme!);
    }

    SynapseBridgeLog.info('SynxPackage: Extracted $id to $targetDir');
  }

  /// Validate the package
  List<String> validate() {
    final errors = <String>[];

    if (id.isEmpty) errors.add('id is required');
    if (name.isEmpty) errors.add('name is required');
    if (version.isEmpty) errors.add('version is required');
    if (script.isEmpty) errors.add('plugin.js is empty');
    if (actions.isEmpty) errors.add('at least one action is required');

    ///TODO : FIX THIS REGEX SHIT
    // Validate ID format (reverse domain notation)
    // if (RegExp(r'^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$')
    //     .hasMatch(id)) {
    //   errors.add('id must be in reverse domain notation (e.g., com.author.plugin)');
    // }

    // Validate version format (semver)
    if (!RegExp(r'^\d+\.\d+\.\d+$').hasMatch(version)) {
      errors.add('version must be in semver format (x.y.z)');
    }

    return errors;
  }

  Map<String, dynamic> _manifestJson({required String? contentHash}) {
    return {
      'manifestVersion': manifestVersion,
      'id': id,
      'name': name,
      'version': version,
      'description': description,
      'author': author,
      if (authorUrl != null) 'authorUrl': authorUrl,
      if (homepage != null) 'homepage': homepage,
      if (license != null) 'license': license,
      if (minSynapseVersion != null) 'minSynapseVersion': minSynapseVersion,
      'security': {
        'allowedDomains': security.allowedDomains,
        'permissions': security.permissions,
        if (contentHash != null) 'contentHash': contentHash,
        if (security.allowedApps.isNotEmpty)
          'allowedApps': security.allowedApps,
      },
      if (connections.isNotEmpty)
        'connections': connections.map((item) => item.toJson()).toList(),
      'actions': actions.map((item) => item.toJson()).toList(),
      if (categories.isNotEmpty) 'categories': categories,
      if (keywords.isNotEmpty) 'keywords': keywords,
    };
  }
}

/// Security configuration for a .synx package
class SynxSecurity {
  final List<String> allowedDomains;
  final List<String> permissions;
  final String? contentHash;

  /// Apps this plugin is allowed to target via AppleScript.
  final List<String> allowedApps;

  const SynxSecurity({
    this.allowedDomains = const [],
    this.permissions = const ['network'],
    this.contentHash,
    this.allowedApps = const [],
  });
}

/// Exception thrown when parsing or validating a .synx package
class SynxPackageException implements Exception {
  final String message;
  SynxPackageException(this.message);

  @override
  String toString() => 'SynxPackageException: $message';
}

