/// Represents a Synapse Plugin loaded from a manifest.
class SynapsePlugin {
  final int manifestVersion = 2;
  final String id;
  final String name;
  final String version;
  final String description;
  final String author;

  // Optional icon path
  final String? iconPath;

  // Icon identifier/name from manifest
  final String? icon;

  // Path to plugin.js on disk (for execution)
  final String? scriptPath;

  // Security configuration
  final PluginSecurityConfig security;

  // MCP server allowlists derived from action requirements
  final List<McpServerConfig> mcpServers;

  // Manifest v2 named connections and action contracts
  final List<PluginConnectionConfig> connections;
  final List<PluginActionConfig> actions;

  // Input schema for validation
  final Map<String, dynamic> inputSchema;

  // Supported intents
  final List<String> triggers;

  // Enabled state (user toggle)
  bool isEnabled;

  SynapsePlugin({
    required this.id,
    required this.name,
    this.version = '1.0.0',
    this.description = '',
    this.author = '',
    this.iconPath,
    this.icon,
    this.scriptPath,
    this.security = const PluginSecurityConfig(),
    this.mcpServers = const [],
    this.connections = const [],
    this.actions = const [],
    this.inputSchema = const {},
    this.triggers = const [],
    this.isEnabled = true,
  });

  @override
  String toString() =>
      'SynapsePlugin(id: $id, name: $name, triggers: $triggers)';
}

/// Parses a plugin from a directory containing manifest.json and plugin.js
class PluginManifestParser {
  /// Load a plugin from a directory
  ///
  /// Expected structure:
  /// - manifest.json
  /// - plugin.js
  /// - icon.png (optional)
  static Future<SynapsePlugin?> loadFromDirectory(String dirPath) async {
    final manifestFile = File('$dirPath/manifest.json');
    final scriptFile = File('$dirPath/plugin.js');

    if (!await manifestFile.exists()) {
      return null;
    }

    if (!await scriptFile.exists()) {
      return null;
    }

    try {
      final manifestJson =
          jsonDecode(await manifestFile.readAsString()) as Map<String, dynamic>;
      validateManifestV2Contract(manifestJson);
      final script = await scriptFile.readAsString();

      // Parse security config
      final securityJson =
          manifestJson['security'] as Map<String, dynamic>? ?? {};
      final security = PluginSecurityConfig(
        allowedDomains: List<String>.from(securityJson['allowedDomains'] ?? []),
        permissions: List<String>.from(
            securityJson['permissions'] ?? ['network', 'launch']),
        scriptHash: securityJson['scriptHash'] as String?,
        allowedApps: List<String>.from(securityJson['allowedApps'] ?? []),
      );

      final connections =
          (manifestJson['connections'] as List<dynamic>? ?? const [])
              .map(
                (item) => PluginConnectionConfig.fromJson(
                  Map<String, dynamic>.from(item as Map),
                ),
              )
              .toList();
      final actions = (manifestJson['actions'] as List<dynamic>? ?? const [])
          .map(
            (item) => PluginActionConfig.fromJson(
              Map<String, dynamic>.from(item as Map),
            ),
          )
          .toList();
      final mcpServers = deriveMcpServerConfigs(actions);
      final derivedTriggers =
          actions.expand((action) => action.triggers).toSet().toList();
      final inputSchema = actions.first.inputSchema;

      // SECURITY: Verify hash if provided
      if (security.scriptHash != null) {
        final actualHash = 'sha256-${sha256.convert(utf8.encode(script))}';
        if (actualHash != security.scriptHash) {
          throw SecurityException(
              'Hash mismatch for ${manifestJson['id']}. Expected ${security.scriptHash}, got $actualHash');
        }
      }

      // Check for icon
      final iconFile = File('$dirPath/icon.png');
      final iconPath = await iconFile.exists() ? iconFile.path : null;

      return SynapsePlugin(
        id: manifestJson['id'] as String,
        name: manifestJson['name'] as String,
        version: manifestJson['version'] as String? ?? '1.0.0',
        description: manifestJson['description'] as String? ?? '',
        author: manifestJson['author'] as String? ?? '',
        iconPath: iconPath,
        icon: manifestJson['icon'] as String?,
        scriptPath: scriptFile.path,
        security: security,
        mcpServers: mcpServers,
        connections: connections,
        actions: actions,
        inputSchema: inputSchema,
        triggers: derivedTriggers,
      );
    } catch (e) {
      SynapseBridgeLog.error(
          'PluginManifestParser: Failed to load from $dirPath', e);
      rethrow;
    }
  }

  /// Generate a hash for a script (for manifest creation)
  static String generateScriptHash(String script) {
    return 'sha256-${sha256.convert(utf8.encode(script))}';
  }
}

void validateManifestV2Contract(Map<String, dynamic> manifest) {
  if (manifest['manifestVersion'] != 2) {
    throw const FormatException('manifestVersion must be 2');
  }

  final legacyFields = ['triggers', 'inputSchema', 'auth', 'mcpServers']
      .where(manifest.containsKey)
      .toList();
  if (legacyFields.isNotEmpty) {
    throw FormatException(
      'Manifest v1 fields are not supported: ${legacyFields.join(', ')}',
    );
  }

  final actions = manifest['actions'];
  if (actions is! List || actions.isEmpty) {
    throw const FormatException('actions must contain at least one action');
  }
}

List<McpServerConfig> deriveMcpServerConfigs(
  List<PluginActionConfig> actions,
) {
  final servers = <String, McpServerConfig>{};

  for (final requirement in actions
      .expand((action) => action.requirements)
      .where((requirement) => requirement.kind == 'mcp')) {
    final alias = requirement.alias;
    final serverId = requirement.serverId;
    if (alias == null || serverId == null) continue;

    servers[alias] = McpServerConfig(
      name: alias,
      serverId: serverId,
      tools: {
        ...?servers[alias]?.tools,
        ...requirement.tools,
      }.toList(),
    );
  }

  return servers.values.toList();
}

