import 'dart:convert';
import 'dart:io';

import 'package:drift/drift.dart';
import 'package:path_provider/path_provider.dart';
import 'package:http/http.dart' as http;
import 'package:synapse_bridge/synapse_bridge.dart';
import '../../core/domain/repositories/plugin_repository.dart';
import '../../data/data_sources/local/database/daos/local_database_dao.dart';
import '../../data/data_sources/local/database/database.dart';
import '../../services/logger/logger_service.dart';

/// Implementation of PluginRepository using SQLite for plugin registry.
///
/// Stores plugin manifest data in SQLite for fast queries and background
/// isolate support. Only plugin.js files are kept on the file system.
class PluginRepositoryImpl implements PluginRepository {
  final SynapseLocalDao _dao;

  PluginRepositoryImpl(this._dao);

  @override
  Future<List<SynapsePlugin>> getAllPlugins() async {
    final rows = await _dao.getAllPlugins();
    return rows.map(_rowToPlugin).toList();
  }

  @override
  Future<List<SynapsePlugin>> getEnabledPlugins() async {
    final rows = await _dao.getEnabledPlugins();
    return rows.map(_rowToPlugin).toList();
  }

  @override
  Future<SynapsePlugin?> getPlugin(String id) async {
    final row = await _dao.getPlugin(id);
    return row != null ? _rowToPlugin(row) : null;
  }

  @override
  Future<void> refreshPlugins() async {
    // With SQLite, we don't need to scan the file system.
    // The DB is already the source of truth.
    // This method is kept for interface compatibility.
    LoggerService.info('PluginRepository: Using SQLite as source of truth');
  }

  // =========================================================================
  // Installation Methods
  // =========================================================================

  /// Install a plugin from a .synx file
  @override
  Future<SynapsePlugin> installFromSynx(String filePath) async {
    LoggerService.info('PluginRepository: Installing from .synx: $filePath');

    final package = await SynxPackage.fromFile(filePath);
    return _installPackage(package);
  }

  /// Install a plugin from a .synx URL
  @override
  Future<SynapsePlugin> installFromUrl(String url) async {
    LoggerService.info('PluginRepository: Downloading from URL: $url');

    final response = await http.get(Uri.parse(url));
    if (response.statusCode != 200) {
      throw Exception('Failed to download plugin: HTTP ${response.statusCode}');
    }

    final package = SynxPackage.fromBytes(
      Uint8List.fromList(response.bodyBytes),
    );
    return _installPackage(package);
  }

  /// Install a plugin from bytes (for in-memory .synx data)
  @override
  Future<SynapsePlugin> installFromBytes(Uint8List bytes) async {
    LoggerService.info(
      'PluginRepository: Installing from bytes (${bytes.length} bytes)',
    );

    final package = SynxPackage.fromBytes(bytes);
    return _installPackage(package);
  }

  /// Common installation logic for all sources
  Future<SynapsePlugin> _installPackage(SynxPackage package) async {
    // Validate the package
    final errors = package.validate();
    if (errors.isNotEmpty) {
      throw Exception('Invalid package: ${errors.join(', ')}');
    }

    // Extract to plugins directory (for plugin.js)
    final targetDir = await _getPluginDirectory(package.id);
    await package.extractTo(targetDir.path);

    final scriptPath = '${targetDir.path}/plugin.js';

    // Build security JSON
    final securityJson = {
      'manifestVersion': package.manifestVersion,
      'allowedDomains': package.security.allowedDomains,
      'permissions': package.security.permissions,
      'contentHash': package.security.contentHash,
      'allowedApps': package.security.allowedApps,
      'connections': package.connections.map((e) => e.toJson()).toList(),
      'actions': package.actions.map((e) => e.toJson()).toList(),
    };

    // Insert into SQLite
    await _dao.upsertPlugin(
      InstalledPluginsTableCompanion(
        id: Value(package.id),
        name: Value(package.name),
        version: Value(package.version),
        description: Value(package.description),
        author: Value(package.author),
        icon: Value(null), // Icon data is stored separately if needed
        triggersJson: Value(jsonEncode(package.triggers)),
        inputSchemaJson: Value(jsonEncode(package.inputSchema)),
        securityJson: Value(jsonEncode(securityJson)),
        authJson: const Value(null),
        scriptPath: Value(scriptPath),
        isEnabled: const Value(true),
        installedAt: Value(DateTime.now()),
      ),
    );

    LoggerService.info(
      'PluginRepository: Installed ${package.id} v${package.version}',
    );

    // Return the plugin
    return (await getPlugin(package.id))!;
  }

  // =========================================================================
  // Uninstall & Enable/Disable
  // =========================================================================

  @override
  Future<void> uninstallPlugin(String pluginId) async {
    // Delete from SQLite
    await _dao.deletePlugin(pluginId);

    // Delete plugin files
    final pluginDir = await _getPluginDirectory(pluginId);
    if (await pluginDir.exists()) {
      await pluginDir.delete(recursive: true);
    }

    LoggerService.info('PluginRepository: Uninstalled plugin $pluginId');
  }

  @override
  Future<void> setPluginEnabled(String pluginId, bool enabled) async {
    await _dao.setPluginEnabled(pluginId, enabled);
    LoggerService.info('PluginRepository: $pluginId enabled=$enabled');
  }

  // =========================================================================
  // Helpers
  // =========================================================================

  Future<Directory> _getPluginDirectory(String pluginId) async {
    final docsDir = await getApplicationDocumentsDirectory();
    return Directory('${docsDir.path}/plugins/$pluginId');
  }

  /// Convert a database row to a SynapsePlugin entity
  SynapsePlugin _rowToPlugin(InstalledPluginsTableData row) {
    // Parse JSON fields
    final securityJson = jsonDecode(row.securityJson) as Map<String, dynamic>;
    if (securityJson['manifestVersion'] != 2) {
      throw StateError('Installed plugin ${row.id} is not manifest v2');
    }
    final connections =
        (securityJson['connections'] as List<dynamic>? ?? const [])
            .map(
              (item) => PluginConnectionConfig.fromJson(
                Map<String, dynamic>.from(item as Map),
              ),
            )
            .toList();
    final actions = (securityJson['actions'] as List<dynamic>? ?? const [])
        .map(
          (item) => PluginActionConfig.fromJson(
            Map<String, dynamic>.from(item as Map),
          ),
        )
        .toList();
    if (actions.isEmpty) {
      throw StateError('Installed plugin ${row.id} has no action contracts');
    }
    final mcpServers = deriveMcpServerConfigs(actions);
    final triggers = actions
        .expand((action) => action.triggers)
        .toSet()
        .toList();
    final inputSchema = actions.first.inputSchema;

    return SynapsePlugin(
      id: row.id,
      name: row.name,
      version: row.version,
      description: row.description,
      author: row.author,
      icon: row.icon,
      iconPath: null, // Icons are now referenced by identifier, not path
      scriptPath: row.scriptPath, // Path to plugin.js
      security: PluginSecurityConfig(
        allowedDomains: List<String>.from(securityJson['allowedDomains'] ?? []),
        permissions: List<String>.from(
          securityJson['permissions'] ?? ['network', 'launch'],
        ),
        scriptHash: securityJson['scriptHash'] as String?,
        allowedApps: List<String>.from(securityJson['allowedApps'] ?? const []),
      ),
      mcpServers: mcpServers,
      connections: connections,
      actions: actions,
      inputSchema: inputSchema,
      triggers: triggers,
      isEnabled: row.isEnabled,
    );
  }
}

