import 'dart:convert';
import 'dart:io';

import 'package:drift/drift.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:synapse_bridge/synapse_bridge.dart';
import 'package:synapse/core/domain/repositories/plugin_repository.dart';
import 'package:synapse/services/logger/logger_service.dart';
import 'package:synapse/data/data_sources/local/database/database.dart';
import 'package:synapse/services/plugin/execution_logger.dart';
import 'package:synapse/presentation/widgets/plugin_ui_dialog.dart';
import 'package:synapse/presentation/widgets/plugin_error_dialog.dart';
import 'package:synapse/services/platform/system_bridge_service.dart';
import 'package:synapse/services/auth/oauth_provider_registry.dart';
import 'package:synapse/services/auth/platform_auth_service.dart';
import 'package:synapse/services/mcp/mcp_service.dart';

/// Executes plugins with SDK caching and host-per-plugin pooling.
///
/// This class provides a single entry point for plugin execution:
/// - Resolves pluginId → SynapsePlugin from repository
/// - Loads and caches the SDK on first use
/// - Maintains a pool of hosts (one per plugin) for fast subsequent calls
/// - Handles cleanup when plugins are uninstalled
class PluginExecutor {
  final PluginRepository _pluginRepository;
  final SynapseAppDataBase _database;

  // Cached SDK code (loaded once, reused for all hosts)
  String? _cachedSdk;

  // Host pool: one host per plugin for isolation + performance
  final Map<String, SynapseHost> _hostCache = {};

  // Track which hosts have loaded their plugin script
  final Set<String> _loadedPlugins = {};

  // BuildContext for UI operations (dialogs, toasts)
  BuildContext? _context;

  // Current execution logger (updated before each execution for callback logging)
  ExecutionLogger? _currentLogger;

  // Auth and Config services (optional, for service-based auth)
  final AuthService? _authService;
  final ConfigService? _configService;
  final SystemBridgeService? _systemBridgeService;
  final OAuthProviderRegistry? _oauthProviderRegistry;
  final McpService? _mcpService;

  PluginExecutor(
    this._pluginRepository,
    this._database, {
    AuthService? authService,
    ConfigService? configService,
    SystemBridgeService? systemBridgeService,
    OAuthProviderRegistry? oauthProviderRegistry,
    McpService? mcpService,
  }) : _authService = authService,
       _configService = configService,
       _systemBridgeService = systemBridgeService,
       _oauthProviderRegistry = oauthProviderRegistry,
       _mcpService = mcpService;

  /// Set the BuildContext for UI operations
  void setContext(BuildContext? context) {
    _context = context;
    final authService = _authService;
    if (authService is PlatformAuthService) {
      authService.setAuthContext(context);
    }
  }

  /// Execute a plugin by its ID
  ///
  /// This is the main entry point for plugin execution. It:
  /// 1. Resolves the plugin from repository
  /// 2. Ensures SDK is loaded (cached after first load)
  /// 3. Gets or creates a host for this plugin
  /// 4. Loads the plugin script if not already loaded
  /// 5. Dispatches the intent
  /// 6. Saves execution logs to database
  Future<PluginExecutionResult> execute({
    required String pluginId,
    required String intent,
    required Map<String, dynamic> params,
    int? captureId, // Optional: link logs to a capture
  }) async {
    final logger = ExecutionLogger();
    _currentLogger = logger; // Store for callback logging
    logger.dart('Starting execution: $pluginId/$intent');

    // Create log entry in DB (status: running)
    int? logId;
    if (captureId != null) {
      logId = await _database.synapseLocalDao.insertActionLog(
        ActionExecutionLogsCompanion(
          userSharedId: Value(captureId),
          pluginId: Value(pluginId),
          actionType: Value(intent),
          inputParams: Value(params.toString()),
          status: const Value('running'),
          startedAt: Value(DateTime.now()),
        ),
      );
    }

    try {
      // 1. Resolve plugin from repository
      logger.dart('Resolving plugin from repository');
      final plugin = await _pluginRepository.getPlugin(pluginId);
      if (plugin == null) {
        logger.error('Plugin not found: $pluginId');
        await _saveLogResult(
          logId,
          logger,
          'fail',
          error: 'Plugin not found: $pluginId',
        );
        return PluginExecutionResult(
          status: 'fail',
          error: 'Plugin not found: $pluginId',
        );
      }

      if (!plugin.isEnabled) {
        logger.warn('Plugin is disabled: $pluginId');
        await _saveLogResult(
          logId,
          logger,
          'fail',
          error: 'Plugin is disabled: $pluginId',
        );
        return PluginExecutionResult(
          status: 'fail',
          error: 'Plugin is disabled: $pluginId',
        );
      }

      // 2. Ensure SDK is loaded
      logger.dart('Loading SDK');
      await _ensureSdkLoaded();
      logger.dart('SDK loaded (${_cachedSdk!.length} bytes)');

      // 3. Get or create host for this plugin
      logger.dart('Getting/creating host');
      final host = await _getOrCreateHost(pluginId, plugin, logger);

      // 4. Load plugin script if not already loaded
      if (!_loadedPlugins.contains(pluginId)) {
        logger.dart('Loading plugin script');
        await _loadPluginScript(host, plugin);
        _loadedPlugins.add(pluginId);
        logger.dart('Plugin script loaded');
      }

      // 5. Dispatch the intent
      logger.dart('Dispatching: $intent');
      final result = await host.dispatch(intent, params);

      // 5.5 Show error popup for plugin-reported errors
      if (result.isError && result.message != null && _context != null) {
        logger.dart(
          'Plugin reported error: reason=${result.reason}, message=${result.message}',
        );
        _showPluginErrorDialog(result);
      }

      // 6. Log result
      logger.dart('Execution completed: ${result.status}');
      await _saveLogResult(
        logId,
        logger,
        result.status,
        result: result.data?.toString(),
      );

      return result;
    } catch (e, stack) {
      logger.error('Execution failed: $e');
      LoggerService.error('PluginExecutor: Execution failed', e, stack);
      await _saveLogResult(logId, logger, 'error', error: e.toString());
      return PluginExecutionResult(status: 'fail', error: e.toString());
    }
  }

  /// Save log result to database (fire-and-forget for performance)
  Future<void> _saveLogResult(
    int? logId,
    ExecutionLogger logger,
    String status, {
    String? result,
    String? error,
  }) async {
    if (logId == null) return;

    final durationMs = logger.stop();

    // Update asynchronously - don't block return
    _database.synapseLocalDao.updateActionLog(
      logId,
      ActionExecutionLogsCompanion(
        status: Value(status),
        executionLogs: Value(logger.toJson()),
        result: Value(result ?? error),
        durationMs: Value(durationMs),
        completedAt: Value(DateTime.now()),
      ),
    );
  }

  /// Execute with a pre-fetched SynapsePlugin (bypasses repository lookup)
  // Future<PluginExecutionResult> executeWithPlugin({
  //   required SynapsePlugin plugin,
  //   required String intent,
  //   required Map<String, dynamic> params,
  // }) async {
  //   try {
  //     await _ensureSdkLoaded();
  //     final host = await _getOrCreateHost(plugin.id, plugin);
  //
  //     if (!_loadedPlugins.contains(plugin.id)) {
  //       await _loadPluginScript(host, plugin);
  //       _loadedPlugins.add(plugin.id);
  //     }
  //
  //     return await host.dispatch(intent, params);
  //   } catch (e, stack) {
  //     LoggerService.error('PluginExecutor: Execution failed', e, stack);
  //     return PluginExecutionResult(
  //       status: 'fail',
  //       error: e.toString(),
  //     );
  //   }
  // }

  // ===========================================================================
  // SDK Loading
  // ===========================================================================

  Future<void> _ensureSdkLoaded() async {
    if (_cachedSdk != null) return;

    LoggerService.info('PluginExecutor: Loading SDK from assets...');
    _cachedSdk = await rootBundle.loadString('assets/js/synapse.global.js');
    LoggerService.info(
      'PluginExecutor: SDK loaded (${_cachedSdk!.length} bytes)',
    );
  }

  // ===========================================================================
  // Host Pool Management
  // ===========================================================================

  Future<SynapseHost> _getOrCreateHost(
    String pluginId,
    SynapsePlugin plugin, [
    ExecutionLogger? logger,
  ]) async {
    if (_hostCache.containsKey(pluginId)) {
      logger?.dart('Reusing cached host');
      return _hostCache[pluginId]!;
    }

    logger?.dart('Creating new host for $pluginId');
    LoggerService.info('PluginExecutor: Creating new host for $pluginId');

    final host = SynapseHost();
    await host.init();
    logger?.dart('Host initialized');
    await host.loadSdk(_cachedSdk!);
    logger?.dart('SDK loaded into host');

    // Configure security
    await host.loadPlugin(
      pluginId: pluginId,
      securityConfig: PluginSecurityConfig(
        allowedDomains: plugin.security.allowedDomains,
        permissions: plugin.security.permissions,
        allowedApps: plugin.security.allowedApps,
      ),
    );
    logger?.dart('Plugin security configured');

    // Setup callbacks
    _setupHostCallbacks(host, pluginId, plugin, logger);

    // Inject auth and config services
    host.authService = _authService;
    host.configService = _configService;

    _hostCache[pluginId] = host;
    return host;
  }

  void _setupHostCallbacks(
    SynapseHost host,
    String pluginId,
    SynapsePlugin plugin, [
    ExecutionLogger? _,
  ]) {
    // NOTE: We use _currentLogger (instance var) instead of the passed logger
    // so callbacks always log to the active execution's logger, even for cached hosts.

    // UI Show callback - displays WebView with plugin HTML
    host.onUiShow = (html, options) async {
      _currentLogger?.dart('UI Show requested');
      LoggerService.info('PluginExecutor: UI Show requested');
      if (_context == null) {
        _currentLogger?.error('No context for UI show');
        return null;
      }

      final result = await showDialog<dynamic>(
        context: _context!,
        barrierDismissible: false,
        builder: (ctx) => PluginUiDialog(
          html: html,
          title: options?['title'] as String? ?? 'Plugin',
        ),
      );

      _currentLogger?.dart('UI Show closed with result: $result');
      return result;
    };

    // Toast callback
    host.onToast = (message, durationMs) {
      _currentLogger?.dart('Toast: $message');
      LoggerService.info('PluginExecutor: Toast: $message');
      if (_context != null) {
        ScaffoldMessenger.of(_context!).showSnackBar(
          SnackBar(
            content: Text(message),
            duration: Duration(milliseconds: durationMs),
          ),
        );
      }
    };

    // Confirm callback
    host.onConfirm = (message, confirmLabel, cancelLabel) async {
      _currentLogger?.dart('Confirm dialog: $message');
      LoggerService.info('PluginExecutor: Confirm: $message');
      if (_context == null) return true;

      final result = await showDialog<bool>(
        context: _context!,
        builder: (ctx) => AlertDialog(
          title: const Text('Confirm'),
          content: Text(message),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(ctx).pop(false),
              child: Text(cancelLabel ?? 'Cancel'),
            ),
            TextButton(
              onPressed: () => Navigator.of(ctx).pop(true),
              child: Text(confirmLabel ?? 'OK'),
            ),
          ],
        ),
      );

      _currentLogger?.dart('Confirm result: $result');
      return result ?? false;
    };

    PluginConnectionConfig? connectionFor(String alias) {
      for (final connection in plugin.connections) {
        if (connection.alias == alias) return connection;
      }
      return null;
    }

    PluginConnectionConfig? connectionForProvider(String provider) {
      for (final connection in plugin.connections) {
        if (connection.provider == provider) return connection;
      }
      return null;
    }

    // Provider callbacks resolve through manifest v2 connections.
    host.onAuthCheck = (provider) async {
      _currentLogger?.dart('Auth check: $provider');
      LoggerService.info('PluginExecutor: Auth check for $provider');

      if (_authService == null) {
        _currentLogger?.error('AuthService not available');
        return false;
      }

      return _authService.isAuthenticated(pluginId, provider);
    };

    host.onAuthRequest = (providerName) async {
      _currentLogger?.dart('Auth request: $providerName');
      LoggerService.info('PluginExecutor: Auth request for $providerName');

      if (_authService == null) {
        _currentLogger?.error('AuthService not available');
        return false;
      }

      final connection = connectionForProvider(providerName);
      if (connection == null || connection.type != 'oauth2') {
        _currentLogger?.error(
          'Plugin has no OAuth connection for $providerName',
        );
        return false;
      }

      if (_oauthProviderRegistry == null) {
        _currentLogger?.error('OAuthProviderRegistry not available');
        return false;
      }

      // Resolve OAuth2Provider from marketplace vault
      final provider = await _oauthProviderRegistry.resolveProvider(
        pluginId: pluginId,
        provider: connection.provider,
        scopes: connection.scopes,
      );

      return _authService.authenticate(pluginId, provider);
    };

    host.onConnectionCheck = (alias) async {
      final connection = connectionFor(alias);
      if (connection == null || _authService == null) return false;
      if (connection.type == 'none') return true;

      final authService = _authService;
      if (authService is PlatformAuthService) {
        return authService.isConnectionGranted(pluginId, alias);
      }
      return authService.isAuthenticated(pluginId, connection.provider);
    };

    host.onConnectionConnect = (alias) async {
      final connection = connectionFor(alias);
      if (connection == null || _authService == null) return false;
      if (connection.type == 'none') return true;
      if (connection.type == 'api_key') {
        final authService = _authService;
        if (authService is! PlatformAuthService) return false;
        if (await authService.isConnectionGranted(pluginId, alias)) {
          return true;
        }
        final apiKey = await _promptForApiKey(
          alias: alias,
          provider: connection.provider,
        );
        if (apiKey == null) return false;
        await authService.saveApiKey(
          pluginId: pluginId,
          provider: connection.provider,
          apiKey: apiKey,
        );
        await authService.grantConnection(
          pluginId: pluginId,
          alias: alias,
          provider: connection.provider,
          scopes: connection.scopes,
        );
        return true;
      }

      final authService = _authService;
      if (connection.type == 'mcp_oauth') {
        if (authService is! PlatformAuthService || _mcpService == null) {
          return false;
        }
        if (await authService.isConnectionGranted(pluginId, alias)) {
          return true;
        }

        McpServerConfig? server;
        for (final candidate in plugin.mcpServers) {
          if (candidate.name == alias) {
            server = candidate;
            break;
          }
        }
        final descriptor = await _mcpService.getConnectionDescriptor(
          server?.serverId ?? server?.name ?? alias,
        );
        if (descriptor.authType != 'mcp-oauth' ||
            descriptor.remoteUrl == null) {
          _currentLogger?.error(
            'MCP server "$alias" has no remote MCP OAuth deployment',
          );
          return false;
        }
        final credentialProvider = await authService.authenticateMcpConnection(
          pluginId: pluginId,
          provider: descriptor.provider,
          serverUrl: descriptor.remoteUrl!,
        );
        if (credentialProvider == null) return false;
        await authService.grantConnection(
          pluginId: pluginId,
          alias: alias,
          provider: credentialProvider,
          scopes: connection.scopes,
        );
        return true;
      }

      if (_oauthProviderRegistry == null) return false;

      var connected = await _authService.isAuthenticated(
        pluginId,
        connection.provider,
      );
      if (!connected) {
        final provider = await _oauthProviderRegistry.resolveProvider(
          pluginId: pluginId,
          provider: connection.provider,
          scopes: connection.scopes,
        );
        connected = await _authService.authenticate(pluginId, provider);
      }
      if (!connected) return false;

      if (authService is PlatformAuthService) {
        await authService.grantConnection(
          pluginId: pluginId,
          alias: alias,
          provider: connection.provider,
          scopes: connection.scopes,
        );
      }
      return true;
    };

    host.onConnectionDisconnect = (alias) async {
      final authService = _authService;
      if (authService is PlatformAuthService) {
        await authService.revokeConnectionGrant(pluginId, alias);
      }
    };

    host.onConnectionAccessToken = (alias) async {
      final connection = connectionFor(alias);
      if (connection == null || _authService == null) return null;
      final authService = _authService;
      if (authService is PlatformAuthService) {
        return authService.getConnectionAccessToken(pluginId, alias);
      }
      return authService.getAccessToken(pluginId, connection.provider);
    };

    // Status callback (logs from JS side)
    host.onStatusChanged = (status, data) {
      _currentLogger?.js('Status: $status, Data=${_prettyJson(data['data'])}');
      LoggerService.verbose(
        'PluginExecutor: Status=$status, Data=${_prettyJson(data['data'])}',
      );
    };

    // System Bridge Callbacks
    host.onRunShortcut = (name, input) async {
      _currentLogger?.dart('System Trigger: Run Shortcut "$name"');
      LoggerService.info(
        'PluginExecutor: System Trigger: Run Shortcut "$name"',
      );

      if (_systemBridgeService == null) {
        _currentLogger?.error('SystemBridgeService not available');
        throw Exception('System integration not available');
      }

      try {
        await _systemBridgeService.runShortcut(name, input);
        _currentLogger?.dart('System Trigger: Shortcut launched successfully');
      } catch (e) {
        _currentLogger?.error('System Trigger: Shortcut failed - $e');
        rethrow;
      }
    };

    host.onSendIntent = (options) async {
      _currentLogger?.dart('System Trigger: Send Intent');
      LoggerService.info('PluginExecutor: System Trigger: Send Intent');

      if (_systemBridgeService == null) {
        _currentLogger?.error('SystemBridgeService not available');
        throw Exception('System integration not available');
      }

      try {
        await _systemBridgeService.sendIntent(options);
        _currentLogger?.dart('System Trigger: Intent launched successfully');
      } catch (e) {
        _currentLogger?.error('System Trigger: Intent failed - $e');
        rethrow;
      }
    };

    // AppleScript callback
    host.onRunAppleScript = (script, timeoutMs) async {
      _currentLogger?.dart(
        'System Trigger: AppleScript (${script.length} chars)',
      );
      LoggerService.info('PluginExecutor: System Trigger: AppleScript');

      if (_systemBridgeService == null) {
        _currentLogger?.error('SystemBridgeService not available');
        throw Exception('System integration not available');
      }

      try {
        final allowedApps = plugin.security.allowedApps;
        final result = await _systemBridgeService.runAppleScript(
          script,
          timeoutMs: timeoutMs,
          allowedApps: allowedApps,
        );
        _currentLogger?.dart('System Trigger: AppleScript completed');
        return result;
      } catch (e) {
        _currentLogger?.error('System Trigger: AppleScript failed - $e');
        rethrow;
      }
    };

    // Platform callback
    host.onGetPlatform = () {
      return _systemBridgeService?.getPlatform() ?? 'unknown';
    };

    // EventKit Calendar callbacks
    host.onCalendarGetCalendars = () async {
      _currentLogger?.dart('System Trigger: Get Calendars');
      LoggerService.info('PluginExecutor: System Trigger: Get Calendars');

      if (_systemBridgeService == null) {
        _currentLogger?.error('SystemBridgeService not available');
        throw Exception('System integration not available');
      }

      try {
        final calendars = await _systemBridgeService.getCalendars();
        _currentLogger?.dart(
          'System Trigger: Got ${calendars.length} calendars',
        );
        return calendars;
      } catch (e) {
        _currentLogger?.error('System Trigger: Get Calendars failed - $e');
        rethrow;
      }
    };

    host.onCalendarGetEvents = (options) async {
      _currentLogger?.dart('System Trigger: Get Calendar Events');
      LoggerService.info('PluginExecutor: System Trigger: Get Calendar Events');

      if (_systemBridgeService == null) {
        _currentLogger?.error('SystemBridgeService not available');
        throw Exception('System integration not available');
      }

      try {
        final events = await _systemBridgeService.getCalendarEvents(
          startDate: options['startDate'] as String,
          endDate: options['endDate'] as String,
          calendarId: options['calendarId'] as String?,
        );
        _currentLogger?.dart('System Trigger: Got ${events.length} events');
        return events;
      } catch (e) {
        _currentLogger?.error('System Trigger: Get Events failed - $e');
        rethrow;
      }
    };

    host.onCalendarCreateEvent = (event) async {
      _currentLogger?.dart('System Trigger: Create Calendar Event');
      LoggerService.info(
        'PluginExecutor: System Trigger: Create Calendar Event',
      );

      if (_systemBridgeService == null) {
        _currentLogger?.error('SystemBridgeService not available');
        throw Exception('System integration not available');
      }

      try {
        final result = await _systemBridgeService.createCalendarEvent(
          title: event['title'] as String,
          startDate: event['startDate'] as String,
          endDate: event['endDate'] as String,
          notes: event['notes'] as String?,
          location: event['location'] as String?,
          calendarId: event['calendarId'] as String?,
          allDay: event['allDay'] as bool? ?? false,
        );
        _currentLogger?.dart('System Trigger: Event created');
        return result;
      } catch (e) {
        _currentLogger?.error('System Trigger: Create Event failed - $e');
        rethrow;
      }
    };

    // MCP callback
    host.onMcpCallTool = (serverName, toolName, args, options) async {
      _currentLogger?.dart('MCP callTool: $serverName.$toolName');
      LoggerService.info('PluginExecutor: MCP callTool: $serverName.$toolName');

      if (_mcpService == null) {
        return {
          'success': false,
          'error': 'MCP service not configured',
          'code': 'NOT_CONFIGURED',
        };
      }

      final declaredServers = plugin.mcpServers;
      McpServerConfig? declaredServer;
      for (final server in declaredServers) {
        if (server.name == serverName) {
          declaredServer = server;
          break;
        }
      }

      if (declaredServer == null) {
        return {
          'success': false,
          'error': 'Server "$serverName" not declared in manifest',
          'code': 'UNDECLARED_SERVER',
        };
      }

      if (!declaredServer.tools.contains(toolName)) {
        return {
          'success': false,
          'error': 'Tool "$toolName" not in allowlist for "$serverName"',
          'code': 'TOOL_NOT_ALLOWED',
        };
      }

      final timeoutMsRaw = options['timeoutMs'];
      final timeoutMs = timeoutMsRaw is int
          ? timeoutMsRaw
          : int.tryParse(timeoutMsRaw?.toString() ?? '') ?? 10000;
      final routingPolicy =
          options['routingPolicy'] as String? ?? 'prefer-local';
      final connection = connectionFor(declaredServer.name);
      final declaredAuthProvider = connection?.provider;
      McpCallAuthContext? authContext;
      if (declaredAuthProvider != null &&
          declaredAuthProvider.isNotEmpty &&
          _authService != null) {
        final platformAuth = _authService is PlatformAuthService
            ? _authService
            : null;
        final grant = connection != null && platformAuth != null
            ? await platformAuth.getConnectionGrant(pluginId, connection.alias)
            : null;
        final authProvider = grant?.provider ?? declaredAuthProvider;
        final accessToken = connection != null && platformAuth != null
            ? await platformAuth.getConnectionAccessToken(
                pluginId,
                connection.alias,
              )
            : await _authService.getAccessToken(pluginId, authProvider);
        if (accessToken != null && accessToken.isNotEmpty) {
          authContext = McpCallAuthContext(
            provider: authProvider,
            grantId: grant?.id ?? 'connection:$pluginId:${connection!.alias}',
            accessToken: accessToken,
          );
        }
      }
      final platform =
          Platform.isMacOS || Platform.isWindows || Platform.isLinux
          ? 'desktop'
          : 'mobile';

      return _mcpService.callTool(
        pluginId: pluginId,
        serverName: serverName,
        toolName: toolName,
        arguments: args,
        timeoutMs: timeoutMs,
        routingPolicy: routingPolicy,
        platform: platform,
        declaredServers: declaredServers,
        authContext: authContext,
      );
    };
  }

  String _prettyJson(dynamic data) {
    try {
      final encoder = const JsonEncoder.withIndent('  ');
      return encoder.convert(data);
    } catch (_) {
      return data.toString();
    }
  }

  Future<String?> _promptForApiKey({
    required String alias,
    required String provider,
  }) async {
    final context = _context;
    if (context == null) {
      _currentLogger?.error(
        'Cannot connect "$alias" without an active UI context',
      );
      return null;
    }

    final controller = TextEditingController();
    try {
      return await showDialog<String>(
        context: context,
        barrierDismissible: false,
        builder: (dialogContext) => AlertDialog(
          title: Text('Connect $provider'),
          content: TextField(
            controller: controller,
            autofocus: true,
            obscureText: true,
            enableSuggestions: false,
            autocorrect: false,
            decoration: const InputDecoration(
              labelText: 'API key',
              helperText: 'Stored securely and never exposed to plugin code.',
            ),
            onSubmitted: (value) {
              final trimmed = value.trim();
              if (trimmed.isNotEmpty) {
                Navigator.of(dialogContext).pop(trimmed);
              }
            },
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () {
                final value = controller.text.trim();
                if (value.isNotEmpty) {
                  Navigator.of(dialogContext).pop(value);
                }
              },
              child: const Text('Connect'),
            ),
          ],
        ),
      );
    } finally {
      controller.dispose();
    }
  }

  /// Show an error dialog for plugin-reported errors
  void _showPluginErrorDialog(PluginExecutionResult result) {
    if (_context == null) return;
    showDialog(
      context: _context!,
      builder: (ctx) => PluginErrorDialog(
        reason: result.reason,
        message: result.message ?? result.error ?? 'An unknown error occurred',
      ),
    );
  }

  // ===========================================================================
  // Plugin Script Loading
  // ===========================================================================

  Future<void> _loadPluginScript(SynapseHost host, SynapsePlugin plugin) async {
    if (plugin.scriptPath == null) {
      throw Exception('Plugin ${plugin.id} has no scriptPath');
    }

    final scriptFile = File(plugin.scriptPath!);
    if (!await scriptFile.exists()) {
      throw Exception('Plugin script not found: ${plugin.scriptPath}');
    }

    final script = await scriptFile.readAsString();
    LoggerService.info(
      'PluginExecutor: Loading script for ${plugin.id} (${script.length} bytes)',
    );

    // Execute the plugin script in the host
    await host.loadPluginScript(script);
  }

  // ===========================================================================
  // Lifecycle Management
  // ===========================================================================

  /// Remove a plugin's host from the cache (call when plugin is uninstalled)
  void removePlugin(String pluginId) {
    final host = _hostCache.remove(pluginId);
    if (host != null) {
      host.dispose();
      _loadedPlugins.remove(pluginId);
      LoggerService.info('PluginExecutor: Removed host for $pluginId');
    }
  }

  /// Clear all hosts (call on memory pressure or app going to background)
  void clearAllHosts() {
    for (final host in _hostCache.values) {
      host.dispose();
    }
    _hostCache.clear();
    _loadedPlugins.clear();
    LoggerService.info('PluginExecutor: Cleared all hosts');
  }

  /// Dispose the executor completely
  void dispose() {
    clearAllHosts();
    _cachedSdk = null;
    LoggerService.info('PluginExecutor: Disposed');
  }
}

