import 'dart:async';
import 'dart:convert';
import 'package:fjs/fjs.dart';
import 'package:http/http.dart' as http;

import 'auth_service.dart';
import 'config_service.dart';
import 'logger.dart';

/// Result of a plugin execution
class PluginExecutionResult {
  final String status; // 'success' | 'fail' | 'error'
  final dynamic data;
  final String? error;
  final String? link;
  final String? reason; // e.g. 'no_databases', 'auth_failed'
  final String? message; // Human-readable error message from plugin

  PluginExecutionResult({
    required this.status,
    this.data,
    this.error,
    this.link,
    this.reason,
    this.message,
  });

  bool get isSuccess => status == 'success';
  bool get isError => status == 'error' || status == 'fail';

  factory PluginExecutionResult.fromJson(Map<String, dynamic> json) {
    return PluginExecutionResult(
      status: json['status'] ?? 'fail',
      data: json['data'],
      error: json['error'],
      link: json['link'],
      reason: json['reason'] as String?,
      message: json['message'] as String?,
    );
  }

  Map<String, dynamic> toJson() => {
        'status': status,
        'data': data,
        'error': error,
        'link': link,
        'reason': reason,
        'message': message,
      };
}

/// Security configuration for a plugin
class PluginSecurityConfig {
  final List<String> allowedDomains;
  final List<String> permissions;
  final String? scriptHash;

  /// Apps this plugin is allowed to target via AppleScript.
  /// When non-empty, the host validates `tell application "X"` targets.
  final List<String> allowedApps;

  const PluginSecurityConfig({
    this.allowedDomains = const [],
    this.permissions = const ['network', 'launch'],
    this.scriptHash,
    this.allowedApps = const [],
  });

  bool get canMakeNetworkCalls => permissions.contains('network');
  bool get canLaunchUrls => permissions.contains('launch');
  bool get canShowUI => permissions.contains('ui');
  bool get canUseStorage => permissions.contains('storage');
  bool get canRunAppleScript => permissions.contains('applescript');
  bool get canAccessCalendar => permissions.contains('calendar');
  bool get canAccessReminders => permissions.contains('reminders');
  bool get canUseMcp => permissions.contains('mcp');

  bool isDomainAllowed(String host) {
    return true;
    // if (allowedDomains.isEmpty) return true; // No whitelist = allow all
    // return allowedDomains.any((domain) =>
    //   host == domain || host.endsWith('.$domain')
    // );
  }
}

/// Authentication configuration for a plugin

// =============================================================================
// Callback Types for Host Integration
// =============================================================================

/// Called when a plugin finishes execution
typedef SynapseStatusCallback = void Function(String status, dynamic data);

/// Called when plugin requests UI display. Return the data from UI.
typedef SynapseUiShowCallback = Future<dynamic> Function(
    String html, Map<String, dynamic>? options);

/// Called when plugin requests a toast message
typedef SynapseToastCallback = void Function(String message, int durationMs);

/// Called when plugin requests a confirmation dialog
typedef SynapseConfirmCallback = Future<bool> Function(
    String message, String? confirmLabel, String? cancelLabel);

/// Called to check authentication status
typedef SynapseAuthCheckCallback = Future<bool> Function(String provider);

/// Called to trigger authentication flow
typedef SynapseAuthRequestCallback = Future<bool> Function(String provider);

/// Called to logout from a provider
typedef SynapseAuthLogoutCallback = Future<void> Function(String provider);

/// Called to inspect or change a manifest v2 named connection grant.
typedef SynapseConnectionCheckCallback = Future<bool> Function(String alias);
typedef SynapseConnectionConnectCallback = Future<bool> Function(String alias);
typedef SynapseConnectionDisconnectCallback = Future<void> Function(
    String alias);
typedef SynapseConnectionAccessTokenCallback = Future<String?> Function(
  String alias,
);

/// Called to upload a file
typedef SynapseUploadCallback = Future<Map<String, dynamic>> Function({
  required String fileRef,
  required String url,
  String method,
  Map<String, String>? headers,
  String? fieldName,
  Map<String, String>? formFields,
});

/// Called to execute an AppleScript (macOS only)
typedef SynapseAppleScriptCallback = Future<String?> Function(
    String script, int timeoutMs);

/// Called to query calendar events
typedef SynapseCalendarGetEventsCallback = Future<List<Map<String, dynamic>>>
    Function(Map<String, dynamic> options);

/// Called to create a calendar event
typedef SynapseCalendarCreateEventCallback = Future<Map<String, dynamic>>
    Function(Map<String, dynamic> event);

/// Called to list available calendars
typedef SynapseCalendarGetCalendarsCallback = Future<List<Map<String, dynamic>>>
    Function();

/// Called to get the current platform
typedef SynapsePlatformCallback = String Function();

/// Called when a plugin invokes `synapse.mcp.callTool()`.
typedef SynapseMcpCallToolCallback = Future<Map<String, dynamic>> Function(
  String serverName,
  String toolName,
  Map<String, dynamic> arguments,
  Map<String, dynamic> options,
);

/// The Synapse Host - Bridge between Flutter and JS Plugins
///
/// Implements the Host side of the Synapse SDK protocol.
///
/// Security features:
/// - Domain whitelisting for network requests
/// - Script hash verification
/// - Disposable runtime (create fresh for each execution)
///
/// Usage:
/// ```dart
/// final host = SynapseHost();
/// await host.init();
/// await host.loadSdk(sdkSource);
/// await host.loadPlugin(securityConfig: config, pluginId: 'my-plugin');
/// final result = await host.dispatch('create_item', {'title': 'Test'});
/// host.dispose();
/// ```
class SynapseHost {
  late JsEngine _engine;
  PluginSecurityConfig _securityConfig = const PluginSecurityConfig();
  String _currentPluginId = 'default';
  String? _loadedScript;

  /// Get the currently loaded plugin script
  String? getLoadedScript() => _loadedScript;

  // Storage for plugin data (per-plugin)
  final Map<String, Map<String, dynamic>> _storage = {};

  // Callback for status updates (for UI binding)
  SynapseStatusCallback? onStatusChanged;

  // UI Callbacks
  SynapseUiShowCallback? onUiShow;
  SynapseToastCallback? onToast;
  SynapseConfirmCallback? onConfirm;

  // auth
  SynapseAuthCheckCallback? onAuthCheck;
  SynapseAuthRequestCallback? onAuthRequest;
  SynapseAuthLogoutCallback? onAuthLogout;
  SynapseConnectionCheckCallback? onConnectionCheck;
  SynapseConnectionConnectCallback? onConnectionConnect;
  SynapseConnectionDisconnectCallback? onConnectionDisconnect;
  SynapseConnectionAccessTokenCallback? onConnectionAccessToken;

  // Upload Callback
  SynapseUploadCallback? onUpload;

  // System Callbacks (Automation Bridging)
  // Called to run an iOS Shortcut
  Future<void> Function(String name, String? input)? onRunShortcut;
  // Called to send an Android Intent
  Future<void> Function(Map<String, dynamic> options)? onSendIntent;
  // Called to execute AppleScript (macOS only)
  SynapseAppleScriptCallback? onRunAppleScript;
  // Called to get calendar events
  SynapseCalendarGetEventsCallback? onCalendarGetEvents;
  // Called to create a calendar event
  SynapseCalendarCreateEventCallback? onCalendarCreateEvent;
  // Called to list calendars
  SynapseCalendarGetCalendarsCallback? onCalendarGetCalendars;
  // Called to get current platform
  SynapsePlatformCallback? onGetPlatform;
  // Called to execute an MCP tool.
  SynapseMcpCallToolCallback? onMcpCallTool;

  // Service-based auth and config (preferred over callbacks)
  AuthService? authService;
  ConfigService? configService;

  // Completer for async execution
  PluginExecutionResult? _lastResult;
  bool _hasFinished = false;

  /// Initialize the JS runtime and setup bridges.
  ///
  /// Engine: FJS (Rust + QuickJS). Each host gets an isolated QuickJS
  /// runtime — one per plugin — preserving the per-plugin isolation the
  /// host pool relies on.
  Future<void> init() async {
    // Load the FJS native library once per process.
    if (!_fjsInitialized) {
      await LibFjs.init();
      _fjsInitialized = true;
    }

    _hasFinished = false;
    _lastResult = null;

    // Builtins are intentionally minimal. The SDK routes ALL I/O (fetch,
    // storage, mcp, auth, calendar, ...) through the bridge so the host can
    // enforce the domain allowlist and credential vault. We must NOT enable
    // FJS's built-in `fetch`, or plugins could bypass host security.
    _engine = await JsEngine.create(
      builtins: const JsBuiltinOptions(console: true),
    );

    // Register the async bridge. JS reaches the host via `fjs.bridge_call`.
    await _engine.init(bridge: _bridgeCallback);

    // Inject a shim that maps the SDK's `sendMessage(channel, message)` calls
    // onto FJS's `fjs.bridge_call`. This keeps the shipped SDK asset
    // (synapse.global.js) 100% unchanged.
    await _engine.eval(source: const JsCode.code(_kSendMessageShim));

    SynapseBridgeLog.info('SynapseHost: Runtime initialized (FJS)');
  }

  /// Whether the FJS native library has been loaded for this process.
  static bool _fjsInitialized = false;

  /// Host-side bridge entry point invoked when JS calls `fjs.bridge_call`.
  ///
  /// Receives a JSON envelope `{channel, message}` produced by the shim from
  /// the SDK's `sendMessage(...)`. Processing is dispatched asynchronously to
  /// preserve the original fire-and-forget `onMessage` semantics: the bridge
  /// returns immediately and responses flow back through `_resolvePromise`.
  Future<JsResult> _bridgeCallback(JsValue value) async {
    try {
      final raw = value.value;
      if (raw is! String) {
        SynapseBridgeLog.warning(
            'SynapseHost: bridge received non-string: ${value.typeName()}');
        return const JsResult.ok(JsValue.none());
      }
      final envelope = jsonDecode(raw) as Map<String, dynamic>;
      final message = envelope['message'];
      final decoded = message is String ? jsonDecode(message) : message;
      // Fire-and-forget — mirrors the original onMessage callback.
      unawaited(_handleBridgeMessage(decoded as Map<String, dynamic>));
    } catch (e, st) {
      SynapseBridgeLog.error('SynapseHost: bridge callback failed', e, st);
    }
    return const JsResult.ok(JsValue.none());
  }

  /// Maps the SDK's `sendMessage(channel, message)` global onto FJS's
  /// `fjs.bridge_call`. Injected after engine init so the shipped SDK asset
  /// (synapse.global.js) needs no changes.
  static const String _kSendMessageShim = r"""
(function () {
  globalThis.sendMessage = function (channel, message) {
    try {
      var p = fjs.bridge_call(
        JSON.stringify({ channel: channel, message: message })
      );
      if (p && typeof p.catch === 'function') {
        // Swallow: real errors are reported by the host through
        // synapse._bridge.resolve(). A rejected bridge_call only happens if
        // the Dart side threw before returning a JsResult.
        p.catch(function () {});
      }
    } catch (e) {
      // Synchronous invocation error — ignore for parity with fire-and-forget
      // sendMessage semantics. Host logs separately.
    }
  };
})();
""";

  /// Load the Synapse SDK (synapse.global.js)
  Future<void> loadSdk(String sdkSource) async {
    await _engine.eval(source: JsCode.code(sdkSource));
    SynapseBridgeLog.info('SynapseHost: SDK loaded');
  }

  /// Load a plugin's security config and set the current plugin ID
  ///
  /// [securityConfig] defines the security constraints for the plugin.
  /// [pluginId] is used for storage isolation between plugins.
  Future<void> loadPlugin({
    PluginSecurityConfig securityConfig = const PluginSecurityConfig(),
    String pluginId = 'default',
  }) async {
    _securityConfig = securityConfig;
    _currentPluginId = pluginId;
    SynapseBridgeLog.info('SynapseHost: Plugin loaded (id: $pluginId)');
  }

  /// Load and execute a plugin's JavaScript code
  ///
  /// [script] is the contents of plugin.js
  /// This should be called after [loadPlugin] to ensure security is configured.
  Future<void> loadPluginScript(String script) async {
    _loadedScript = script;
    await _engine.eval(source: JsCode.code(script));
    SynapseBridgeLog.info(
        'SynapseHost: Plugin script executed (${script.length} bytes)');
  }

  /// Dispatch an intent to the JS Runtime
  ///
  /// [intent] is the registered intent name in the plugin.
  /// [params] are the parameters to pass to the handler.
  ///
  /// Returns a [PluginExecutionResult] with the outcome.
  Future<PluginExecutionResult> dispatch(
      String intent, Map<String, dynamic> params) async {
    _hasFinished = false;
    _lastResult = null;

    final paramsJson = jsonEncode(params);
    final code = "synapse._dispatch('$intent', $paramsJson)";

    // FJS throws on JS eval errors (flutter_js returned JsEvalResult.isError).
    try {
      await _engine.eval(source: JsCode.code(code));
    } catch (e) {
      SynapseBridgeLog.error('SynapseHost: Dispatch Error: $e');
      return PluginExecutionResult(
        status: 'fail',
        error: e.toString(),
      );
    }

    // Wait for the 'finished' message. FJS's async engine drives promises,
    // timers, and bridge calls automatically, so no manual
    // executePendingJob() pumping is required (unlike flutter_js).
    final timeout = DateTime.now().add(const Duration(seconds: 30));
    while (!_hasFinished && DateTime.now().isBefore(timeout)) {
      await Future.delayed(const Duration(milliseconds: 50));
    }

    if (!_hasFinished) {
      return PluginExecutionResult(
        status: 'fail',
        error: 'Plugin execution timed out',
      );
    }

    return _lastResult ??
        PluginExecutionResult(status: 'fail', error: 'No result');
  }

  /// Handle messages coming FROM Javascript
  Future<void> _handleBridgeMessage(Map<String, dynamic> message) async {
    final type = message['type'] as String?;
    final id = message['id'] as String?;
    final payload = message['payload'];

    SynapseBridgeLog.verbose('SynapseHost: Received message type=$type');

    switch (type) {
      // Network (new fetch API)
      case 'fetch':
        await _handleFetch(id, payload as Map<String, dynamic>);
        break;

      // Legacy network (backwards compatibility)
      case 'network_request':
        await _handleFetch(id, payload as Map<String, dynamic>);
        break;

      // UI
      case 'ui_show':
        await _handleUiShow(id, payload as Map<String, dynamic>);
        break;

      case 'ui_toast':
        _handleToast(payload as Map<String, dynamic>);
        break;

      case 'ui_confirm':
        await _handleConfirm(id, payload as Map<String, dynamic>);
        break;

      // Auth
      case 'auth_check':
        await _handleAuthCheck(id, payload as Map<String, dynamic>);
        break;

      case 'auth_authenticate':
        await _handleAuthRequest(id, payload as Map<String, dynamic>);
        break;

      case 'auth_logout':
        await _handleAuthLogout(id, payload as Map<String, dynamic>);
        break;

      case 'auth_getToken':
        await _handleAuthGetToken(id, payload as Map<String, dynamic>);
        break;

      // Manifest v2 connections
      case 'connection_check':
        await _handleConnectionCheck(id, payload as Map<String, dynamic>);
        break;

      case 'connection_connect':
        await _handleConnectionConnect(id, payload as Map<String, dynamic>);
        break;

      case 'connection_disconnect':
        await _handleConnectionDisconnect(id, payload as Map<String, dynamic>);
        break;

      // Config (uses ConfigService)
      case 'config_get':
        await _handleConfigGet(id, payload as Map<String, dynamic>);
        break;

      case 'config_set':
        await _handleConfigSet(id, payload as Map<String, dynamic>);
        break;

      // Storage
      case 'storage_get':
        await _handleStorageGet(id, payload as Map<String, dynamic>);
        break;

      case 'storage_set':
        _handleStorageSet(payload as Map<String, dynamic>);
        break;

      case 'storage_delete':
        _handleStorageDelete(payload as Map<String, dynamic>);
        break;

      case 'storage_clear':
        _handleStorageClear();
        break;

      // Upload
      case 'upload':
        await _handleUpload(id, payload as Map<String, dynamic>);
        break;

      // Status
      case 'finished':
        _hasFinished = true;
        _lastResult =
            PluginExecutionResult.fromJson(payload as Map<String, dynamic>);
        SynapseBridgeLog.info(
            'SynapseHost: Action finished with status=${_lastResult?.status}');
        onStatusChanged?.call('finished', payload);
        break;

      case 'log':
        final msg = payload is Map ? payload['message'] : payload.toString();
        SynapseBridgeLog.info('JS_PLUGIN: $msg');
        break;

      // System (Shortcuts & Intents)
      case 'system_runShortcut':
        await _handleSystemRunShortcut(id, payload as Map<String, dynamic>);
        break;

      case 'system_sendIntent':
        await _handleSystemSendIntent(id, payload as Map<String, dynamic>);
        break;

      // System (AppleScript)
      case 'system_runAppleScript':
        await _handleSystemRunAppleScript(id, payload as Map<String, dynamic>);
        break;

      // System (Platform)
      case 'system_platform':
        _handleSystemPlatform(id);
        break;

      // System (EventKit Calendar)
      case 'system_calendar_getCalendars':
        await _handleCalendarGetCalendars(id);
        break;

      case 'system_calendar_getEvents':
        await _handleCalendarGetEvents(id, payload as Map<String, dynamic>);
        break;

      case 'system_calendar_createEvent':
        await _handleCalendarCreateEvent(id, payload as Map<String, dynamic>);
        break;

      // MCP
      case 'mcp_callTool':
        await _handleMcpCallTool(id, payload as Map<String, dynamic>);
        break;

      default:
        SynapseBridgeLog.warning('SynapseHost: Unknown message type: $type');
    }
  }

  // =============================================================================
  // Network Handler (Fetch API)
  // =============================================================================

  Future<void> _handleFetch(String? id, Map<String, dynamic> req) async {
    if (id == null) return;

    try {
      final url = Uri.parse(req['url'] as String);
      final provider = req['provider'] as String?;
      final connection = req['connection'] as String?;

      // SECURITY: Check domain whitelist
      if (!_securityConfig.isDomainAllowed(url.host)) {
        SynapseBridgeLog.warning(
            'SynapseHost: Blocked request to ${url.host} (not in whitelist)');
        _resolvePromise(id, null, error: 'Domain ${url.host} is not allowed');
        return;
      }

      // SECURITY: Check if network permission is granted
      if (!_securityConfig.canMakeNetworkCalls) {
        SynapseBridgeLog.warning(
            'SynapseHost: Plugin does not have network permission');
        _resolvePromise(id, null, error: 'Network permission not granted');
        return;
      }

      final method = (req['method'] as String?) ?? 'GET';
      const Map<String, String> defaultHeaders = {
        'User-Agent': 'PostmanRuntime/7.32.3',
        'Accept': '*/*',
      };
      final headers = {
        ...defaultHeaders,
        if (req['headers'] != null) ...Map<String, String>.from(req['headers']),
      };
      final body = req['body'];

      // Manifest v2 connection aliases take precedence over legacy providers.
      if (connection != null && connection.isNotEmpty) {
        if (onConnectionCheck == null || onConnectionAccessToken == null) {
          _resolvePromise(id, null, error: 'Connection service not configured');
          return;
        }

        var isConnected = await onConnectionCheck!(connection);
        if (!isConnected && onConnectionConnect != null) {
          isConnected = await onConnectionConnect!(connection);
        }
        if (!isConnected) {
          _resolvePromise(id, null,
              error: 'Connection "$connection" is not available');
          return;
        }

        final token = await onConnectionAccessToken!(connection);
        if (token == null || token.isEmpty) {
          _resolvePromise(id, null,
              error: 'Failed to obtain connection credential');
          return;
        }
        headers.putIfAbsent('Authorization', () => 'Bearer $token');
      } else if (provider != null && provider.isNotEmpty) {
        // Legacy provider-based authentication.
        if (authService == null) {
          _resolvePromise(id, null, error: 'AuthService not configured');
          return;
        }

        bool isAuth = true;
        if (onAuthCheck != null) {
          isAuth = await onAuthCheck!(provider);
        } else {
          isAuth =
              await authService!.isAuthenticated(_currentPluginId, provider);
        }

        if (!isAuth) {
          if (onAuthRequest != null) {
            final success = await onAuthRequest!(provider);
            if (!success) {
              _resolvePromise(id, null, error: 'Authentication failed');
              return;
            }
          } else {
            _resolvePromise(id, null, error: 'Not authenticated');
            return;
          }
        }

        final token =
            await authService!.getAccessToken(_currentPluginId, provider);
        if (token == null || token.isEmpty) {
          _resolvePromise(id, null, error: 'Failed to obtain access token');
          return;
        }

        headers.putIfAbsent('Authorization', () => 'Bearer $token');
      }

      SynapseBridgeLog.info('SynapseHost: HTTP $method to $url');

      http.Response response;
      Future<http.Response> doRequest() async {
        switch (method.toUpperCase()) {
          case 'POST':
            return http.post(url, headers: headers, body: body);
          case 'PUT':
            return http.put(url, headers: headers, body: body);
          case 'DELETE':
            return http.delete(url, headers: headers);
          case 'PATCH':
            return http.patch(url, headers: headers, body: body);
          default:
            return http.get(url, headers: headers);
        }
      }

      response = await doRequest();

      // Retry once on 401 for manifest v2 connection requests.
      if (response.statusCode == 401 &&
          connection != null &&
          connection.isNotEmpty &&
          onConnectionConnect != null &&
          onConnectionAccessToken != null) {
        final success = await onConnectionConnect!(connection);
        if (success) {
          final token = await onConnectionAccessToken!(connection);
          if (token != null && token.isNotEmpty) {
            headers['Authorization'] = 'Bearer $token';
            response = await doRequest();
          }
        }
      } else if (response.statusCode == 401 &&
          provider != null &&
          provider.isNotEmpty) {
        // Retry once on 401 for legacy provider-auth requests.
        if (onAuthRequest != null) {
          final success = await onAuthRequest!(provider);
          if (success) {
            final token =
                await authService!.getAccessToken(_currentPluginId, provider);
            if (token != null && token.isNotEmpty) {
              headers['Authorization'] = 'Bearer $token';
              response = await doRequest();
            }
          }
        }
      }

      // Build response matching SynapseResponseData interface
      final statusText = _getStatusText(response.statusCode);
      final bridgeResponse = {
        'status': response.statusCode,
        'ok': response.statusCode >= 200 && response.statusCode < 300,
        'statusText': statusText,
        'headers': response.headers,
        'body': response.body,
      };

      _resolvePromise(id, bridgeResponse);
    } catch (e) {
      SynapseBridgeLog.error('SynapseHost: Network Error', e);
      _resolvePromise(id, null, error: e.toString());
    }
  }

  String _getStatusText(int code) {
    const statusTexts = {
      200: 'OK',
      201: 'Created',
      204: 'No Content',
      400: 'Bad Request',
      401: 'Unauthorized',
      403: 'Forbidden',
      404: 'Not Found',
      500: 'Internal Server Error',
    };
    return statusTexts[code] ?? 'Unknown';
  }

  // =============================================================================
  // UI Handlers
  // =============================================================================

  Future<void> _handleUiShow(String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    if (onUiShow == null) {
      _resolvePromise(id, null, error: 'UI display not implemented');
      return;
    }

    try {
      final html = payload['html'] as String?;
      final options = payload['options'] as Map<String, dynamic>?;

      if (html == null) {
        _resolvePromise(id, null, error: 'No HTML content provided');
        return;
      }

      final result = await onUiShow!(html, options);
      _resolvePromise(id, result);
    } catch (e) {
      _resolvePromise(id, null, error: e.toString());
    }
  }

  void _handleToast(Map<String, dynamic> payload) {
    final message = payload['message'] as String? ?? '';
    final duration = payload['duration'] as int? ?? 3000;
    onToast?.call(message, duration);
  }

  Future<void> _handleConfirm(String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    if (onConfirm == null) {
      _resolvePromise(id, true);
      return;
    }

    try {
      final message = payload['message'] as String? ?? '';
      final confirmLabel = payload['confirmLabel'] as String?;
      final cancelLabel = payload['cancelLabel'] as String?;

      final result = await onConfirm!(message, confirmLabel, cancelLabel);
      _resolvePromise(id, result);
    } catch (e) {
      _resolvePromise(id, false);
    }
  }

  // =============================================================================
  // Auth Handlers
  // =============================================================================

  Future<void> _handleAuthCheck(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    final provider = payload['provider'] as String? ?? '';

    if (onAuthCheck == null) {
      _resolvePromise(id, false);
      return;
    }

    try {
      final isAuth = await onAuthCheck!(provider);
      _resolvePromise(id, isAuth);
    } catch (e) {
      _resolvePromise(id, false);
    }
  }

  Future<void> _handleAuthRequest(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    final provider = payload['provider'] as String? ?? '';

    if (onAuthRequest == null) {
      _resolvePromise(id, null, error: 'Authentication not implemented');
      return;
    }

    try {
      final success = await onAuthRequest!(provider);
      if (success) {
        _resolvePromise(id, null);
      } else {
        _resolvePromise(id, null, error: 'Authentication failed');
      }
    } catch (e) {
      _resolvePromise(id, null, error: e.toString());
    }
  }

  Future<void> _handleAuthLogout(
      String? id, Map<String, dynamic> payload) async {
    final provider = payload['provider'] as String? ?? '';

    try {
      await onAuthLogout?.call(provider);
      if (id != null) {
        _resolvePromise(id, null);
      }
    } catch (e) {
      if (id != null) {
        _resolvePromise(id, null, error: e.toString());
      }
    }
  }

  /// Get access token using AuthService (preferred over callback)
  Future<void> _handleAuthGetToken(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    final provider = payload['provider'] as String? ?? '';

    if (authService == null) {
      _resolvePromise(id, null, error: 'AuthService not configured');
      return;
    }

    try {
      final token =
          await authService!.getAccessToken(_currentPluginId, provider);
      if (token != null) {
        _resolvePromise(id, token);
      } else {
        _resolvePromise(id, null, error: 'Not authenticated');
      }
    } catch (e) {
      _resolvePromise(id, null, error: e.toString());
    }
  }

  Future<void> _handleConnectionCheck(
    String? id,
    Map<String, dynamic> payload,
  ) async {
    if (id == null) return;
    final alias = payload['alias'] as String? ?? '';
    if (onConnectionCheck == null) {
      _resolvePromise(id, false);
      return;
    }

    try {
      _resolvePromise(id, await onConnectionCheck!(alias));
    } catch (_) {
      _resolvePromise(id, false);
    }
  }

  Future<void> _handleConnectionConnect(
    String? id,
    Map<String, dynamic> payload,
  ) async {
    if (id == null) return;
    final alias = payload['alias'] as String? ?? '';
    if (onConnectionConnect == null) {
      _resolvePromise(id, null, error: 'Connection service not configured');
      return;
    }

    try {
      final connected = await onConnectionConnect!(alias);
      if (connected) {
        _resolvePromise(id, null);
      } else {
        _resolvePromise(id, null, error: 'Connection failed');
      }
    } catch (error) {
      _resolvePromise(id, null, error: error.toString());
    }
  }

  Future<void> _handleConnectionDisconnect(
    String? id,
    Map<String, dynamic> payload,
  ) async {
    if (id == null) return;
    final alias = payload['alias'] as String? ?? '';
    if (onConnectionDisconnect == null) {
      _resolvePromise(id, null, error: 'Connection service not configured');
      return;
    }

    try {
      await onConnectionDisconnect!(alias);
      _resolvePromise(id, null);
    } catch (error) {
      _resolvePromise(id, null, error: error.toString());
    }
  }

  // =============================================================================
  // Config Handlers (uses ConfigService)
  // =============================================================================

  Future<void> _handleConfigGet(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    final key = payload['key'] as String? ?? '';

    if (configService == null) {
      _resolvePromise(id, null, error: 'ConfigService not configured');
      return;
    }

    try {
      final value = await configService!.get(_currentPluginId, key);
      _resolvePromise(id, value);
    } catch (e) {
      _resolvePromise(id, null, error: e.toString());
    }
  }

  Future<void> _handleConfigSet(
      String? id, Map<String, dynamic> payload) async {
    final key = payload['key'] as String? ?? '';
    final value = payload['value'] as String? ?? '';

    if (configService == null) {
      if (id != null) {
        _resolvePromise(id, null, error: 'ConfigService not configured');
      }
      return;
    }

    try {
      await configService!.set(_currentPluginId, key, value);
      if (id != null) {
        _resolvePromise(id, null);
      }
    } catch (e) {
      if (id != null) {
        _resolvePromise(id, null, error: e.toString());
      }
    }
  }

  // =============================================================================
  // Storage Handlers
  // =============================================================================

  Future<void> _handleStorageGet(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    final key = payload['key'] as String? ?? '';
    final pluginStorage = _storage[_currentPluginId] ?? {};
    final value = pluginStorage[key];

    _resolvePromise(id, value);
  }

  void _handleStorageSet(Map<String, dynamic> payload) {
    final key = payload['key'] as String? ?? '';
    final value = payload['value'];

    _storage.putIfAbsent(_currentPluginId, () => {});
    _storage[_currentPluginId]![key] = value;
  }

  void _handleStorageDelete(Map<String, dynamic> payload) {
    final key = payload['key'] as String? ?? '';
    _storage[_currentPluginId]?.remove(key);
  }

  void _handleStorageClear() {
    _storage[_currentPluginId]?.clear();
  }

  // =============================================================================
  // Upload Handler
  // =============================================================================

  Future<void> _handleUpload(String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    if (onUpload == null) {
      _resolvePromise(
          id, {'success': false, 'error': 'Upload not implemented'});
      return;
    }

    try {
      final result = await onUpload!(
        fileRef: payload['fileRef'] as String? ?? '',
        url: payload['url'] as String? ?? '',
        method: payload['method'] as String? ?? 'POST',
        headers: Map<String, String>.from(payload['headers'] ?? {}),
        fieldName: payload['fieldName'] as String?,
        formFields: Map<String, String>.from(payload['formFields'] ?? {}),
      );

      _resolvePromise(id, {
        'success': true,
        'response': result,
      });
    } catch (e) {
      _resolvePromise(id, {
        'success': false,
        'error': e.toString(),
      });
    }
  }

  // =============================================================================
  // System Handlers
  // =============================================================================

  Future<void> _handleSystemRunShortcut(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    if (onRunShortcut == null) {
      _resolvePromise(id, null,
          error: 'System shortcuts not implemented on host');
      return;
    }

    try {
      final name = payload['name'] as String?;
      final input = payload['input'] as String?;

      if (name == null) {
        _resolvePromise(id, null, error: 'Shortcut name is required');
        return;
      }

      await onRunShortcut!(name, input);
      _resolvePromise(id, null);
    } catch (e) {
      _resolvePromise(id, null, error: e.toString());
    }
  }

  Future<void> _handleSystemSendIntent(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    if (onSendIntent == null) {
      _resolvePromise(id, null,
          error: 'System intents not implemented on host');
      return;
    }

    try {
      await onSendIntent!(payload);
      _resolvePromise(id, null);
    } catch (e) {
      _resolvePromise(id, null, error: e.toString());
    }
  }

  // =============================================================================
  // AppleScript Handler
  // =============================================================================

  Future<void> _handleSystemRunAppleScript(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    // SECURITY: Check permission
    if (!_securityConfig.canRunAppleScript) {
      SynapseBridgeLog.warning(
          'SynapseHost: Plugin does not have applescript permission');
      _resolvePromise(id, null,
          error:
              'AppleScript permission not granted. Add "applescript" to manifest permissions.');
      return;
    }

    if (onRunAppleScript == null) {
      _resolvePromise(id, null,
          error: 'AppleScript not available on this platform');
      return;
    }

    try {
      final script = payload['script'] as String?;
      final timeoutMs = payload['timeoutMs'] as int? ?? 10000;

      if (script == null || script.isEmpty) {
        _resolvePromise(id, null, error: 'AppleScript source is required');
        return;
      }

      final result = await onRunAppleScript!(script, timeoutMs);
      _resolvePromise(id, result);
    } catch (e) {
      _resolvePromise(id, null, error: e.toString());
    }
  }

  // =============================================================================
  // Platform Handler
  // =============================================================================

  void _handleSystemPlatform(String? id) {
    if (id == null) return;

    if (onGetPlatform != null) {
      _resolvePromise(id, onGetPlatform!());
    } else {
      _resolvePromise(id, 'unknown');
    }
  }

  // =============================================================================
  // EventKit Calendar Handlers
  // =============================================================================

  Future<void> _handleCalendarGetCalendars(String? id) async {
    if (id == null) return;

    // SECURITY: Check permission
    if (!_securityConfig.canAccessCalendar) {
      SynapseBridgeLog.warning(
          'SynapseHost: Plugin does not have calendar permission');
      _resolvePromise(id, null,
          error:
              'Calendar permission not granted. Add "calendar" to manifest permissions.');
      return;
    }

    if (onCalendarGetCalendars == null) {
      _resolvePromise(id, null,
          error: 'Calendar not available on this platform');
      return;
    }

    try {
      final calendars = await onCalendarGetCalendars!();
      _resolvePromise(id, calendars);
    } catch (e) {
      _resolvePromise(id, null, error: e.toString());
    }
  }

  Future<void> _handleCalendarGetEvents(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    // SECURITY: Check permission
    if (!_securityConfig.canAccessCalendar) {
      SynapseBridgeLog.warning(
          'SynapseHost: Plugin does not have calendar permission');
      _resolvePromise(id, null,
          error:
              'Calendar permission not granted. Add "calendar" to manifest permissions.');
      return;
    }

    if (onCalendarGetEvents == null) {
      _resolvePromise(id, null,
          error: 'Calendar not available on this platform');
      return;
    }

    try {
      final startDate = payload['startDate'] as String?;
      final endDate = payload['endDate'] as String?;

      if (startDate == null || endDate == null) {
        _resolvePromise(id, null, error: 'startDate and endDate are required');
        return;
      }

      final events = await onCalendarGetEvents!(payload);
      _resolvePromise(id, events);
    } catch (e) {
      _resolvePromise(id, null, error: e.toString());
    }
  }

  Future<void> _handleCalendarCreateEvent(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    // SECURITY: Check permission
    if (!_securityConfig.canAccessCalendar) {
      SynapseBridgeLog.warning(
          'SynapseHost: Plugin does not have calendar permission');
      _resolvePromise(id, null,
          error:
              'Calendar permission not granted. Add "calendar" to manifest permissions.');
      return;
    }

    if (onCalendarCreateEvent == null) {
      _resolvePromise(id, null,
          error: 'Calendar not available on this platform');
      return;
    }

    try {
      final title = payload['title'] as String?;
      final startDate = payload['startDate'] as String?;
      final endDate = payload['endDate'] as String?;

      if (title == null || title.isEmpty) {
        _resolvePromise(id, null, error: 'Event title is required');
        return;
      }
      if (startDate == null || endDate == null) {
        _resolvePromise(id, null, error: 'startDate and endDate are required');
        return;
      }

      final result = await onCalendarCreateEvent!(payload);
      _resolvePromise(id, result);
    } catch (e) {
      _resolvePromise(id, null, error: e.toString());
    }
  }

  // =============================================================================
  // MCP Handler
  // =============================================================================

  Future<void> _handleMcpCallTool(
      String? id, Map<String, dynamic> payload) async {
    if (id == null) return;

    if (!_securityConfig.canUseMcp) {
      SynapseBridgeLog.warning(
          'SynapseHost: Plugin does not have mcp permission');
      _resolvePromise(id, {
        'success': false,
        'error': 'mcp permission not granted',
        'code': 'PERMISSION_DENIED',
      });
      return;
    }

    if (onMcpCallTool == null) {
      _resolvePromise(id, {
        'success': false,
        'error': 'MCP not configured in host',
        'code': 'NOT_CONFIGURED',
      });
      return;
    }

    try {
      final serverName = payload['serverName'] as String?;
      final toolName = payload['toolName'] as String?;
      final arguments = _readDynamicMap(payload['arguments']);
      final options = _readDynamicMap(payload['options']);

      if (serverName == null || serverName.isEmpty) {
        _resolvePromise(id, {
          'success': false,
          'error': 'serverName is required',
          'code': 'INVALID_REQUEST',
        });
        return;
      }
      if (toolName == null || toolName.isEmpty) {
        _resolvePromise(id, {
          'success': false,
          'error': 'toolName is required',
          'code': 'INVALID_REQUEST',
        });
        return;
      }

      final result = await onMcpCallTool!(
        serverName,
        toolName,
        arguments,
        options,
      );
      _resolvePromise(id, result);
    } catch (e) {
      SynapseBridgeLog.error('SynapseHost: MCP callTool failed', e);
      _resolvePromise(id, {
        'success': false,
        'error': e.toString(),
        'code': 'EXECUTION_ERROR',
      });
    }
  }

  Map<String, dynamic> _readDynamicMap(dynamic value) {
    if (value == null) return <String, dynamic>{};
    if (value is Map<String, dynamic>) return value;
    if (value is Map) return Map<String, dynamic>.from(value);
    throw FormatException('Expected object but received ${value.runtimeType}');
  }

  // =============================================================================
  // Promise Resolution
  // =============================================================================

  void _resolvePromise(String id, dynamic data, {String? error}) {
    final dataJson = jsonEncode(data);
    final errorArg = error != null ? jsonEncode(error) : 'null';

    final code = "synapse._bridge.resolve('$id', $dataJson, $errorArg)";
    // Fire-and-forget: the eval is scheduled on the FJS engine and runs
    // between operations. Matches the original synchronous evaluate() effect
    // of resolving the SDK's pending promise by id.
    unawaited(_engine.eval(source: JsCode.code(code)));
  }

  /// LIFECYCLE: Dispose the runtime
  ///
  /// Always call this when done with the host to free resources.
  void dispose() {
    // FJS close() is async; fire-and-forget to preserve the void dispose()
    // signature so existing callers (host pool teardown) are unchanged.
    unawaited(_engine.close());
    SynapseBridgeLog.info('SynapseHost: Runtime disposed');
  }
}

/// Security exception for plugin loading
class SecurityException implements Exception {
  final String message;
  SecurityException(this.message);

  @override
  String toString() => 'SecurityException: $message';
}

