import 'dart:async';
import 'dart:convert';

import 'package:crypto/crypto.dart';
import 'package:http/http.dart' as http;
import 'package:synapse_bridge/synapse_bridge.dart';
import 'package:synapse/services/mcp/desktop_mcp_runtime_controller.dart';

class McpCallAuthContext {
  final String provider;
  final String grantId;
  final String? accessToken;

  const McpCallAuthContext({
    required this.provider,
    required this.grantId,
    this.accessToken,
  });

  Map<String, dynamic> toJson({required bool includeAccessToken}) => {
    'provider': provider,
    'grantId': grantId,
    if (includeAccessToken && accessToken != null) 'accessToken': accessToken,
  };
}

class McpServerConnectionDescriptor {
  final String serverId;
  final String authType;
  final String provider;
  final String? remoteUrl;

  const McpServerConnectionDescriptor({
    required this.serverId,
    required this.authType,
    required this.provider,
    this.remoteUrl,
  });
}

class McpService {
  final http.Client _http;
  final DesktopMcpRuntimeController? _desktopRuntimeController;
  final String? _baseUrl;
  final String? _bearerToken;
  final Map<String, String> _remoteGrantCache = {};

  McpService.desktop({
    required DesktopMcpRuntimeController runtimeController,
    http.Client? httpClient,
  }) : _desktopRuntimeController = runtimeController,
       _baseUrl = null,
       _bearerToken = null,
       _http = httpClient ?? http.Client();

  McpService.remote({
    required String baseUrl,
    String? bearerToken,
    http.Client? httpClient,
  }) : _desktopRuntimeController = null,
       _baseUrl = baseUrl,
       _bearerToken = bearerToken,
       _http = httpClient ?? http.Client();

  Future<Map<String, dynamic>> callTool({
    required String pluginId,
    required String serverName,
    required String toolName,
    required Map<String, dynamic> arguments,
    required String platform,
    int timeoutMs = 10000,
    String routingPolicy = 'prefer-local',
    List<McpServerConfig>? declaredServers,
    McpCallAuthContext? authContext,
  }) async {
    try {
      final outboundAuthContext =
          _desktopRuntimeController == null && authContext?.accessToken != null
          ? await _exchangeRemoteGrant(
              pluginId: pluginId,
              authContext: authContext!,
            )
          : authContext;
      final url = await _resolveCallUrl();
      final response = await _http
          .post(
            url,
            headers: {
              'Content-Type': 'application/json',
              if (_bearerToken != null) 'Authorization': 'Bearer $_bearerToken',
            },
            body: jsonEncode({
              'pluginId': pluginId,
              'serverName': serverName,
              'toolName': toolName,
              'arguments': arguments,
              'routingPolicy': routingPolicy,
              'timeoutMs': timeoutMs,
              'platform': platform,
              if (declaredServers != null && declaredServers.isNotEmpty)
                'declaredServers': declaredServers
                    .map((server) => server.toJson())
                    .toList(),
              if (outboundAuthContext != null)
                'authContext': outboundAuthContext.toJson(
                  includeAccessToken: _desktopRuntimeController != null,
                ),
            }),
          )
          .timeout(Duration(milliseconds: timeoutMs));

      final decoded = _decodeResponse(response.body);
      if (decoded is! Map<String, dynamic>) {
        return {
          'success': false,
          'error': 'Invalid MCP response format',
          'code': 'INVALID_RESPONSE',
        };
      }

      if (response.statusCode < 200 || response.statusCode >= 300) {
        return {
          'success': false,
          'error': decoded['error'] ?? 'MCP worker error',
          'code': decoded['code'] ?? 'WORKER_ERROR',
          'status': response.statusCode,
          if (decoded['data'] != null) 'data': decoded['data'],
        };
      }

      return decoded;
    } on TimeoutException {
      return {
        'success': false,
        'error': 'MCP call timed out after ${timeoutMs}ms',
        'code': 'TIMEOUT',
      };
    } catch (e) {
      return {'success': false, 'error': e.toString(), 'code': 'NETWORK_ERROR'};
    }
  }

  Future<McpServerConnectionDescriptor> getConnectionDescriptor(
    String serverId,
  ) async {
    final baseUrl = await _resolveBaseUrl();
    final response = await _http.get(
      Uri.parse('$baseUrl/servers/$serverId'),
      headers: {
        'Accept': 'application/json',
        if (_bearerToken != null) 'Authorization': 'Bearer $_bearerToken',
      },
    );
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw StateError(
        'Unable to load MCP server "$serverId": HTTP ${response.statusCode}',
      );
    }

    final decoded = _decodeResponse(response.body);
    if (decoded is! Map<String, dynamic>) {
      throw StateError('Invalid MCP server descriptor');
    }
    final authProfiles =
        decoded['authProfiles'] as List<dynamic>? ?? const <dynamic>[];
    final deployments =
        decoded['deployments'] as List<dynamic>? ?? const <dynamic>[];
    Map<String, dynamic>? authProfile;
    for (final item in authProfiles) {
      final candidate = Map<String, dynamic>.from(item as Map);
      if (candidate['type'] == 'mcp-oauth') {
        authProfile = candidate;
        break;
      }
    }
    Map<String, dynamic>? remoteDeployment;
    for (final item in deployments) {
      final candidate = Map<String, dynamic>.from(item as Map);
      if (candidate['kind'] == 'remote-http') {
        remoteDeployment = candidate;
        break;
      }
    }

    return McpServerConnectionDescriptor(
      serverId: decoded['serverId'] as String? ?? serverId,
      authType: authProfile?['type'] as String? ?? 'none',
      provider: authProfile?['provider'] as String? ?? serverId,
      remoteUrl: remoteDeployment?['url'] as String?,
    );
  }

  Future<Uri> _resolveCallUrl() async {
    final baseUrl = await _resolveBaseUrl();
    return Uri.parse('$baseUrl/call');
  }

  Future<McpCallAuthContext> _exchangeRemoteGrant({
    required String pluginId,
    required McpCallAuthContext authContext,
  }) async {
    final accessToken = authContext.accessToken;
    if (accessToken == null || accessToken.isEmpty) return authContext;

    final cacheKey = sha256
        .convert(
          utf8.encode(
            '$pluginId:${authContext.provider}:${authContext.grantId}:$accessToken',
          ),
        )
        .toString();
    final cachedGrant = _remoteGrantCache[cacheKey];
    if (cachedGrant != null) {
      return McpCallAuthContext(
        provider: authContext.provider,
        grantId: cachedGrant,
      );
    }

    final baseUrl = await _resolveBaseUrl();
    final response = await _http.post(
      Uri.parse('$baseUrl/connections/grants'),
      headers: {
        'Content-Type': 'application/json',
        if (_bearerToken != null) 'Authorization': 'Bearer $_bearerToken',
      },
      body: jsonEncode({
        'pluginId': pluginId,
        'provider': authContext.provider,
        'localGrantId': authContext.grantId,
        'accessToken': accessToken,
      }),
    );
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw StateError(
        'Unable to exchange MCP connection grant: HTTP ${response.statusCode}',
      );
    }
    final decoded = _decodeResponse(response.body);
    if (decoded is! Map<String, dynamic> ||
        decoded['grantId'] is! String ||
        (decoded['grantId'] as String).isEmpty) {
      throw StateError('MCP grant exchange returned no grantId');
    }
    final remoteGrant = decoded['grantId'] as String;
    _remoteGrantCache[cacheKey] = remoteGrant;
    return McpCallAuthContext(
      provider: authContext.provider,
      grantId: remoteGrant,
    );
  }

  Future<String> _resolveBaseUrl() async {
    if (_desktopRuntimeController != null) {
      await _desktopRuntimeController.ensureStarted();
      return _desktopRuntimeController.baseUrl;
    }

    final baseUrl = _baseUrl;
    if (baseUrl == null || baseUrl.isEmpty) {
      throw StateError('MCP base URL is not configured');
    }

    return baseUrl;
  }

  dynamic _decodeResponse(String body) {
    if (body.trim().isEmpty) {
      return const <String, dynamic>{};
    }
    return jsonDecode(body);
  }
}

