import 'package:flutter/foundation.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:http/http.dart' as http;
import 'package:synapse/services/logger/logger_service.dart';
import 'package:synapse_bridge/synapse_bridge.dart';

abstract class OAuthProviderRegistry {
  Future<OAuth2Provider> resolveProvider({
    required String pluginId,
    required String provider,
    required List<String> scopes,
  });
}

class MarketplaceOAuthProviderRegistry implements OAuthProviderRegistry {
  final http.Client _client;
  final String _baseUrl;
  final String? _authToken;

  MarketplaceOAuthProviderRegistry({
    http.Client? client,
    String? baseUrl,
    String? authToken,
  }) : _client = client ?? http.Client(),
       _baseUrl = baseUrl ?? '${dotenv.get('SYNAPSE_MARKETPLACE')}api/v1',
       _authToken = authToken ?? dotenv.maybeGet('OAUTH_INTERNAL_SERVICE_TOKEN');

  @override
  Future<OAuth2Provider> resolveProvider({
    required String pluginId,
    required String provider,
    required List<String> scopes,
  }) async {
    final uri = Uri.parse('$_baseUrl/oauth/credentials/$pluginId/$provider');

    LoggerService.info(
      'OAuthProviderRegistry: Fetching credentials for $pluginId/$provider',
    );

    final headers = <String, String>{
      'Content-Type': 'application/json',
      if (_authToken != null && _authToken.isNotEmpty)
        'Authorization': 'Bearer $_authToken',
    };

    final response = await _client.get(uri, headers: headers);

    if (response.statusCode != 200) {
      throw Exception(
        'Failed to fetch OAuth credentials: HTTP ${response.statusCode} ${response.body}',
      );
    }

    final payload = jsonDecode(response.body);
    final data =
        payload is Map<String, dynamic> &&
            payload['data'] is Map<String, dynamic>
        ? payload['data'] as Map<String, dynamic>
        : (payload as Map<String, dynamic>);

    final metadata = _asStringDynamicMap(data['metadata']);

    final clientId = _readString(data['client_id']);
    final clientSecret = _readString(data['client_secret']);
    final authorizationUrl = _readString(metadata?['authorizationUrl']);
    var tokenUrl = _readString(metadata?['token_url']);
    final redirectUrl = _readString(data['redirect_url']);
    final providerScopes =
        (data['scopes'] as List<dynamic>?)?.cast<String>() ?? const <String>[];
    final scopeMode = _normalizeScopeMode(
      _readString(data['scope_mode']),
      provider,
    );
    final additionalParameters = _asStringDynamicMap(
      metadata?['additional_parameters'],
    );
    final preferWebView =
        (metadata?['prefer_webview'] ?? false)
            as bool;


    if (clientId == null ||
        authorizationUrl == null ||
        tokenUrl == null ||
        redirectUrl == null) {
      throw Exception(
        'OAuth credentials are missing required fields for $pluginId/$provider',
      );
    }

    if (!_isValidOAuthEndpoint(authorizationUrl) ||
        !_isValidOAuthEndpoint(tokenUrl)) {
      throw Exception(
        'OAuth credentials contain invalid endpoint URLs for $pluginId/$provider '
        '(authorizationUrl=$authorizationUrl, tokenUrl=$tokenUrl)',
      );
    }

    // Server-approved scopes are authoritative. Plugin scopes can only narrow
    // what the backend already allows.
    final intersectedScopes = providerScopes.isNotEmpty
        ? (scopes.isEmpty
              ? providerScopes
              : providerScopes.where(scopes.contains).toList())
        : scopes;
    final effectiveScopes = _applyScopeModePolicy(
      scopeMode: scopeMode,
      provider: provider,
      requestedScopes: scopes,
      providerScopes: providerScopes,
      intersectedScopes: intersectedScopes,
      pluginId: pluginId,
    );

    // LoggerService.info(
    //   '[DEBUG] OAuth credentials from backend for $pluginId/$provider:\n'
    //   '  clientId: $clientId\n'
    //   '  clientSecret: ${clientSecret != null ? '${clientSecret.substring(0, 8)}...' : 'null'}\n'
    //   '  authorizationUrl: $authorizationUrl\n'
    //   '  tokenUrl: $tokenUrl\n'
    //   '  redirectUrl: $redirectUrl\n'
    //   '  scopes: $effectiveScopes\n'
    //   '  scopeMode: $scopeMode\n'
    //   '  additionalParameters: $additionalParameters\n'
    //   '  preferWebView: $preferWebView',
    // );

    return OAuth2Provider(
      name: provider,
      clientId: clientId,
      clientSecret: clientSecret,
      authorizationUrl: authorizationUrl,
      tokenUrl: tokenUrl,
      redirectUrl: redirectUrl,
      scopes: effectiveScopes,
      scopeMode: scopeMode,
      additionalParameters: additionalParameters?.cast<String, String>(),
      preferWebView: preferWebView,
    );
  }

  bool _isValidOAuthEndpoint(String url) {
    final uri = Uri.tryParse(url);
    if (uri == null) return false;
    if (!uri.hasScheme) return false;
    if (kReleaseMode) return uri.scheme == 'https';
    return uri.scheme == 'https' || uri.scheme == 'http';
  }

  Map<String, dynamic>? _asStringDynamicMap(dynamic value) {
    if (value is Map<String, dynamic>) return value;
    if (value is Map) return value.cast<String, dynamic>();
    return null;
  }

  String? _readString(dynamic value) {
    if (value is String && value.trim().isNotEmpty) {
      return value.trim();
    }
    return null;
  }

  String _normalizeScopeMode(String? scopeMode, String provider) {
    final mode = scopeMode?.toLowerCase();
    if (mode == 'required' || mode == 'optional' || mode == 'forbidden') {
      return mode!;
    }
    if (provider == 'notion') {
      return 'optional';
    }
    return 'required';
  }

  List<String> _applyScopeModePolicy({
    required String scopeMode,
    required String provider,
    required List<String> requestedScopes,
    required List<String> providerScopes,
    required List<String> intersectedScopes,
    required String pluginId,
  }) {
    if (scopeMode == 'forbidden') {
      if (requestedScopes.isNotEmpty || providerScopes.isNotEmpty) {
        throw Exception(
          'scope_mode=forbidden but scopes were supplied for $pluginId/$provider. '
          'Requested=$requestedScopes ServerApproved=$providerScopes',
        );
      }
      return const <String>[];
    }

    if (scopeMode == 'required') {
      if (providerScopes.isEmpty) {
