        );
      }
      return intersectedScopes;
    }

    // optional
    if (providerScopes.isNotEmpty &&
        requestedScopes.isNotEmpty &&
        intersectedScopes.isEmpty) {
      throw Exception(
        'Requested OAuth scopes are not allowed for $pluginId/$provider. '
        'Requested=$requestedScopes ServerApproved=$providerScopes',
      );
    }
    return intersectedScopes;
  }
}

