import 'dart:typed_data';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:synapse_bridge/synapse_bridge.dart';
import 'package:synapse/core/domain/repositories/plugin_repository.dart';
import 'package:synapse/core/domain/repositories/plugin_store_repository.dart';
import 'package:synapse/data/models/plugin_store_dtos.dart';
import 'package:synapse/services/logger/logger_service.dart';

// =============================================================================
// Events
// =============================================================================

abstract class PluginEvent {}

/// Load installed plugins from local storage
class LoadPlugins extends PluginEvent {}

/// Load available plugins from the marketplace
class LoadStorePlugins extends PluginEvent {}

/// Load details for a locally installed plugin.
class LoadInstalledPluginDetail extends PluginEvent {
  final String pluginId;
  LoadInstalledPluginDetail(this.pluginId);
}

/// Load full marketplace details for a store plugin.
class LoadStorePluginDetail extends PluginEvent {
  final String packageId;
  LoadStorePluginDetail(this.packageId);
}

/// Refresh installed plugins
class RefreshPlugins extends PluginEvent {}

/// Toggle plugin enabled/disabled
class TogglePluginEnabled extends PluginEvent {
  final String pluginId;
  final bool enabled;
  TogglePluginEnabled(this.pluginId, this.enabled);
}

/// Uninstall a plugin
class UninstallPlugin extends PluginEvent {
  final String pluginId;
  UninstallPlugin(this.pluginId);
}

/// Install a plugin from the marketplace store
class InstallFromStore extends PluginEvent {
  final String packageId;
  InstallFromStore(this.packageId);
}

/// Install a plugin from a .synx file path
class InstallFromFile extends PluginEvent {
  final String filePath;
  InstallFromFile(this.filePath);
}

/// Install a plugin from a .synx URL
class InstallFromUrl extends PluginEvent {
  final String url;
  InstallFromUrl(this.url);
}

/// Install a plugin from bytes (in-memory .synx data)
class InstallFromBytes extends PluginEvent {
  final Uint8List bytes;
  InstallFromBytes(this.bytes);
}

/// Search plugins (both installed and store)
class SearchPlugins extends PluginEvent {
  final String query;
  SearchPlugins(this.query);
}

/// Clear any error state
class ClearError extends PluginEvent {}

// =============================================================================
// State
// =============================================================================

class PluginState {
  /// Installed plugins on the device
  final List<SynapsePlugin> installedPlugins;

  /// Available plugins from the marketplace
  final List<PluginListItemDto> storePlugins;

  /// Loading state for installed plugins
  final bool isLoadingLocal;

  /// Loading state for store plugins
  final bool isLoadingStore;

  /// Installing state
  final bool isInstalling;

  /// ID of the plugin being installed (for UI feedback)
  final String? installingPluginId;

  /// Current search query
  final String? searchQuery;

  /// Error message
  final String? error;

  /// Success message
  final String? successMessage;

  /// Currently selected installed plugin for the details screen.
  final SynapsePlugin? selectedInstalledPlugin;

  /// Currently selected marketplace plugin detail.
  final PluginDetailDto? selectedStorePluginDetail;

  /// Loading state for the details screen.
  final bool isLoadingDetail;

  /// Error shown by the details screen.
  final String? detailError;

  const PluginState({
    this.installedPlugins = const [],
    this.storePlugins = const [],
    this.isLoadingLocal = false,
    this.isLoadingStore = false,
    this.isInstalling = false,
    this.installingPluginId,
    this.searchQuery,
    this.error,
    this.successMessage,
    this.selectedInstalledPlugin,
    this.selectedStorePluginDetail,
    this.isLoadingDetail = false,
    this.detailError,
  });

  PluginState copyWith({
    List<SynapsePlugin>? installedPlugins,
    List<PluginListItemDto>? storePlugins,
    bool? isLoadingLocal,
    bool? isLoadingStore,
    bool? isInstalling,
    String? installingPluginId,
    String? searchQuery,
    String? error,
    String? successMessage,
    SynapsePlugin? selectedInstalledPlugin,
    PluginDetailDto? selectedStorePluginDetail,
    bool? isLoadingDetail,
    String? detailError,
    bool clearSelectedInstalledPlugin = false,
    bool clearSelectedStorePluginDetail = false,
  }) {
    return PluginState(
      installedPlugins: installedPlugins ?? this.installedPlugins,
      storePlugins: storePlugins ?? this.storePlugins,
      isLoadingLocal: isLoadingLocal ?? this.isLoadingLocal,
      isLoadingStore: isLoadingStore ?? this.isLoadingStore,
      isInstalling: isInstalling ?? this.isInstalling,
      installingPluginId: installingPluginId,
      searchQuery: searchQuery ?? this.searchQuery,
      error: error,
      successMessage: successMessage,
      selectedInstalledPlugin: clearSelectedInstalledPlugin
          ? null
          : selectedInstalledPlugin ?? this.selectedInstalledPlugin,
      selectedStorePluginDetail: clearSelectedStorePluginDetail
          ? null
          : selectedStorePluginDetail ?? this.selectedStorePluginDetail,
      isLoadingDetail: isLoadingDetail ?? this.isLoadingDetail,
      detailError: detailError,
    );
  }

  /// Get active (enabled) installed plugins
  List<SynapsePlugin> get activePlugins =>
      installedPlugins.where((p) => p.isEnabled).toList();

  /// Get inactive (disabled) installed plugins
  List<SynapsePlugin> get inactivePlugins =>
      installedPlugins.where((p) => !p.isEnabled).toList();

  /// Combined loading state
  bool get isLoading => isLoadingLocal || isLoadingStore;

  /// Filter store plugins to exclude already installed ones
  List<PluginListItemDto> get recommendedPlugins {
    final installedIds = installedPlugins.map((p) => p.id).toSet();
    return storePlugins
        .where((p) => !installedIds.contains(p.packageId))
        .toList();
  }
}

// =============================================================================
// Bloc
// =============================================================================

class PluginBloc extends Bloc<PluginEvent, PluginState> {
  final PluginRepository _pluginRepository;
  final PluginStoreRepository? _storeRepository;

  PluginBloc(this._pluginRepository, {PluginStoreRepository? storeRepository})
    : _storeRepository = storeRepository,
      super(const PluginState()) {
    on<LoadPlugins>(_onLoadPlugins);
    on<LoadStorePlugins>(_onLoadStorePlugins);
    on<LoadInstalledPluginDetail>(_onLoadInstalledPluginDetail);
    on<LoadStorePluginDetail>(_onLoadStorePluginDetail);
    on<RefreshPlugins>(_onRefreshPlugins);
    on<TogglePluginEnabled>(_onTogglePluginEnabled);
    on<UninstallPlugin>(_onUninstallPlugin);
    on<InstallFromStore>(_onInstallFromStore);
    on<InstallFromFile>(_onInstallFromFile);
    on<InstallFromUrl>(_onInstallFromUrl);
    on<InstallFromBytes>(_onInstallFromBytes);
    on<SearchPlugins>(_onSearchPlugins);
    on<ClearError>(_onClearError);
  }

  // ---------------------------------------------------------------------------
  // Load Events
  // ---------------------------------------------------------------------------

  Future<void> _onLoadPlugins(
    LoadPlugins event,
    Emitter<PluginState> emit,
  ) async {
    emit(state.copyWith(isLoadingLocal: true));
    try {
      final plugins = await _pluginRepository.getAllPlugins();
      emit(state.copyWith(installedPlugins: plugins, isLoadingLocal: false));
      LoggerService.info(
        'PluginBloc: Loaded ${plugins.length} installed plugins',
      );
    } catch (e) {
      LoggerService.error('PluginBloc: Failed to load plugins', e);
      emit(state.copyWith(isLoadingLocal: false, error: e.toString()));
    }
  }

  Future<void> _onLoadStorePlugins(
    LoadStorePlugins event,
    Emitter<PluginState> emit,
  ) async {
    final storeRepository = _storeRepository;
    if (storeRepository == null) return;

    emit(state.copyWith(isLoadingStore: true));
    try {
      final plugins = await storeRepository.browsePlugins(
        query: state.searchQuery,
      );
      emit(state.copyWith(storePlugins: plugins, isLoadingStore: false));
      LoggerService.info('PluginBloc: Loaded ${plugins.length} store plugins');
    } catch (e) {
      LoggerService.error('PluginBloc: Failed to load store plugins', e);
      // Don't show error for store - it's non-critical
      emit(state.copyWith(isLoadingStore: false));
    }
  }

  Future<void> _onLoadInstalledPluginDetail(
    LoadInstalledPluginDetail event,
    Emitter<PluginState> emit,
  ) async {
    emit(
      state.copyWith(
        isLoadingDetail: true,
        detailError: null,
        clearSelectedInstalledPlugin: true,
        clearSelectedStorePluginDetail: true,
      ),
    );
    try {
      final plugin = await _pluginRepository.getPlugin(event.pluginId);
      if (plugin == null) {
        emit(
          state.copyWith(
            isLoadingDetail: false,
            detailError: 'Plugin not installed or removed.',
          ),
        );
        return;
      }
      emit(
        state.copyWith(
          selectedInstalledPlugin: plugin,
          isLoadingDetail: false,
          detailError: null,
        ),
      );
    } catch (e) {
      LoggerService.error('PluginBloc: Failed to load plugin detail', e);
      emit(state.copyWith(isLoadingDetail: false, detailError: e.toString()));
    }
  }

  Future<void> _onLoadStorePluginDetail(
    LoadStorePluginDetail event,
    Emitter<PluginState> emit,
  ) async {
    final storeRepository = _storeRepository;
    if (storeRepository == null) {
      emit(state.copyWith(detailError: 'Store not available'));
      return;
    }

    emit(
      state.copyWith(
        isLoadingDetail: true,
        detailError: null,
        clearSelectedInstalledPlugin: true,
        clearSelectedStorePluginDetail: true,
      ),
    );
    try {
      final plugin = await storeRepository.getPluginDetail(event.packageId);
      emit(
        state.copyWith(
          selectedStorePluginDetail: plugin,
          isLoadingDetail: false,
          detailError: null,
        ),
      );
    } catch (e) {
      LoggerService.error('PluginBloc: Failed to load store plugin detail', e);
      emit(state.copyWith(isLoadingDetail: false, detailError: e.toString()));
    }
  }

  Future<void> _onRefreshPlugins(
    RefreshPlugins event,
    Emitter<PluginState> emit,
  ) async {
    emit(state.copyWith(isLoadingLocal: true));
    try {
      await _pluginRepository.refreshPlugins();
      final plugins = await _pluginRepository.getAllPlugins();
      emit(state.copyWith(installedPlugins: plugins, isLoadingLocal: false));
    } catch (e) {
      emit(state.copyWith(isLoadingLocal: false, error: e.toString()));
    }
  }

  // ---------------------------------------------------------------------------
  // Plugin Management Events
  // ---------------------------------------------------------------------------

  Future<void> _onTogglePluginEnabled(
    TogglePluginEnabled event,
    Emitter<PluginState> emit,
  ) async {
    try {
      await _pluginRepository.setPluginEnabled(event.pluginId, event.enabled);

      final updatedPlugins = state.installedPlugins.map((p) {
        if (p.id == event.pluginId) {
          p.isEnabled = event.enabled;
        }
        return p;
      }).toList();

      final selectedPlugin = state.selectedInstalledPlugin;
      if (selectedPlugin?.id == event.pluginId) {
        selectedPlugin!.isEnabled = event.enabled;
      }

      emit(
        state.copyWith(
          installedPlugins: updatedPlugins,
          selectedInstalledPlugin: selectedPlugin,
        ),
      );
      LoggerService.info(
        'PluginBloc: ${event.pluginId} enabled=${event.enabled}',
      );
    } catch (e) {
      emit(state.copyWith(error: e.toString()));
    }
  }

  Future<void> _onUninstallPlugin(
    UninstallPlugin event,
    Emitter<PluginState> emit,
  ) async {
    try {
      await _pluginRepository.uninstallPlugin(event.pluginId);

      final updatedPlugins = state.installedPlugins
          .where((p) => p.id != event.pluginId)
          .toList();
      emit(state.copyWith(installedPlugins: updatedPlugins));
      LoggerService.info('PluginBloc: Uninstalled ${event.pluginId}');
    } catch (e) {
      emit(state.copyWith(error: e.toString()));
    }
  }

  // ---------------------------------------------------------------------------
  // Installation Events
  // ---------------------------------------------------------------------------

  Future<void> _onInstallFromStore(
    InstallFromStore event,
    Emitter<PluginState> emit,
  ) async {
    if (_storeRepository == null) {
      emit(state.copyWith(error: 'Store not available'));
      return;
    }

    emit(
      state.copyWith(isInstalling: true, installingPluginId: event.packageId),
    );
    try {
      final plugin = await _storeRepository.installPlugin(event.packageId);

      final updatedPlugins = List<SynapsePlugin>.from(state.installedPlugins)
        ..add(plugin);
      emit(
        state.copyWith(
          installedPlugins: updatedPlugins,
          isInstalling: false,
          successMessage: 'Installed ${plugin.name} v${plugin.version}',
        ),
      );
      LoggerService.info('PluginBloc: Installed ${plugin.id} from store');
    } catch (e) {
      LoggerService.error('PluginBloc: Install from store failed', e);
      emit(state.copyWith(isInstalling: false, error: e.toString()));
    }
  }

  Future<void> _onInstallFromFile(
    InstallFromFile event,
    Emitter<PluginState> emit,
  ) async {
    emit(state.copyWith(isInstalling: true));
    try {
      final plugin = await _pluginRepository.installFromSynx(event.filePath);

      final updatedPlugins = List<SynapsePlugin>.from(state.installedPlugins)
        ..add(plugin);
      emit(
        state.copyWith(
          installedPlugins: updatedPlugins,
          isInstalling: false,
          successMessage: 'Installed ${plugin.name} v${plugin.version}',
        ),
      );
      LoggerService.info('PluginBloc: Installed ${plugin.id} from file');
    } catch (e) {
      LoggerService.error('PluginBloc: Install from file failed', e);
      emit(state.copyWith(isInstalling: false, error: e.toString()));
    }
  }

  Future<void> _onInstallFromUrl(
    InstallFromUrl event,
    Emitter<PluginState> emit,
  ) async {
    emit(state.copyWith(isInstalling: true));
    try {
      final plugin = await _pluginRepository.installFromUrl(event.url);

      final updatedPlugins = List<SynapsePlugin>.from(state.installedPlugins)
        ..add(plugin);
      emit(
        state.copyWith(
          installedPlugins: updatedPlugins,
          isInstalling: false,
          successMessage: 'Installed ${plugin.name} v${plugin.version}',
        ),
      );
      LoggerService.info('PluginBloc: Installed ${plugin.id} from URL');
    } catch (e) {
      LoggerService.error('PluginBloc: Install from URL failed', e);
      emit(state.copyWith(isInstalling: false, error: e.toString()));
    }
  }

  Future<void> _onInstallFromBytes(
    InstallFromBytes event,
    Emitter<PluginState> emit,
  ) async {
    emit(state.copyWith(isInstalling: true));
    try {
      final plugin = await _pluginRepository.installFromBytes(event.bytes);

      final updatedPlugins = List<SynapsePlugin>.from(state.installedPlugins)
        ..add(plugin);
      emit(
        state.copyWith(
          installedPlugins: updatedPlugins,
          isInstalling: false,
          successMessage: 'Installed ${plugin.name} v${plugin.version}',
        ),
      );
      LoggerService.info('PluginBloc: Installed ${plugin.id} from bytes');
    } catch (e) {
      LoggerService.error('PluginBloc: Install from bytes failed', e);
      emit(state.copyWith(isInstalling: false, error: e.toString()));
    }
  }

  // ---------------------------------------------------------------------------
  // Search & Clear Events
  // ---------------------------------------------------------------------------

  Future<void> _onSearchPlugins(
    SearchPlugins event,
    Emitter<PluginState> emit,
  ) async {
    emit(state.copyWith(searchQuery: event.query));
    // Optionally trigger store search if needed
    if (_storeRepository != null && event.query.isNotEmpty) {
      add(LoadStorePlugins());
    }
  }

  void _onClearError(ClearError event, Emitter<PluginState> emit) {
    emit(state.copyWith(error: null, successMessage: null));
  }
}

