import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:http/http.dart' as http;
import 'package:synapse/core/utils/platform_utils.dart';
import 'package:synapse/services/logger/logger_service.dart';

//A node process controller for MCP
enum DesktopMcpRuntimeStatus {
  disabled,
  starting,
  ready,
  restarting,
  failed,
  stopped,
}

class DesktopMcpRuntimeState {
  final DesktopMcpRuntimeStatus status;
  final String label;
  final String baseUrl;
  final String? detail;
  final int? lastExitCode;
  final bool automaticRetriesExhausted;

  const DesktopMcpRuntimeState({
    required this.status,
    required this.label,
    required this.baseUrl,
    this.detail,
    this.lastExitCode,
    this.automaticRetriesExhausted = false,
  });

  factory DesktopMcpRuntimeState.disabled({required String baseUrl}) {
    return DesktopMcpRuntimeState(
      status: DesktopMcpRuntimeStatus.disabled,
      label: 'MCP Runtime Disabled',
      baseUrl: baseUrl,
      detail: 'Desktop MCP runtime is only available on desktop platforms.',
    );
  }

  factory DesktopMcpRuntimeState.starting({
    required String baseUrl,
    String? detail,
  }) {
    return DesktopMcpRuntimeState(
      status: DesktopMcpRuntimeStatus.starting,
      label: 'MCP Runtime Starting',
      baseUrl: baseUrl,
      detail: detail,
    );
  }

  factory DesktopMcpRuntimeState.ready({
    required String baseUrl,
    String? detail,
  }) {
    return DesktopMcpRuntimeState(
      status: DesktopMcpRuntimeStatus.ready,
      label: 'MCP Runtime Ready',
      baseUrl: baseUrl,
      detail: detail,
    );
  }

  factory DesktopMcpRuntimeState.restarting({
    required String baseUrl,
    String? detail,
  }) {
    return DesktopMcpRuntimeState(
      status: DesktopMcpRuntimeStatus.restarting,
      label: 'MCP Runtime Restarting',
      baseUrl: baseUrl,
      detail: detail,
    );
  }

  factory DesktopMcpRuntimeState.failed({
    required String baseUrl,
    required String detail,
    int? lastExitCode,
    bool automaticRetriesExhausted = false,
  }) {
    return DesktopMcpRuntimeState(
      status: DesktopMcpRuntimeStatus.failed,
      label: 'MCP Runtime Failed',
      baseUrl: baseUrl,
      detail: detail,
      lastExitCode: lastExitCode,
      automaticRetriesExhausted: automaticRetriesExhausted,
    );
  }

  factory DesktopMcpRuntimeState.stopped({
    required String baseUrl,
    String? detail,
  }) {
    return DesktopMcpRuntimeState(
      status: DesktopMcpRuntimeStatus.stopped,
      label: 'MCP Runtime Stopped',
      baseUrl: baseUrl,
      detail: detail,
    );
  }
}

class DesktopMcpRuntimeController {
  DesktopMcpRuntimeController({
    http.Client? httpClient,
    Duration? healthTimeout,
    Duration? healthCheckInterval,
    Duration? restartBaseDelay,
    int maxAutomaticRestartAttempts = 5,
  }) : assert(maxAutomaticRestartAttempts > 0),
       _http = httpClient ?? http.Client(),
       _healthTimeout = healthTimeout ?? const Duration(seconds: 12),
       _healthCheckInterval = healthCheckInterval ?? const Duration(seconds: 10),
       _restartBaseDelay = restartBaseDelay ?? const Duration(seconds: 2),
       _maxAutomaticRestartAttempts = maxAutomaticRestartAttempts,
       _host = _readHost(),
       _port = _readPort(),
       _state = AppPlatform.isDesktop
           ? DesktopMcpRuntimeState.stopped(
               baseUrl: _composeBaseUrl(_readHost(), _readPort()),
               detail: 'Desktop MCP runtime has not started yet.',
             )
           : DesktopMcpRuntimeState.disabled(
               baseUrl: _composeBaseUrl(_readHost(), _readPort()),
             );

  final http.Client _http;
  final Duration _healthTimeout;
  final Duration _healthCheckInterval;
  final Duration _restartBaseDelay;
  final int _maxAutomaticRestartAttempts;
  final String _host;
  final int _port;
  final StreamController<DesktopMcpRuntimeState> _stateController =
      StreamController<DesktopMcpRuntimeState>.broadcast();

  DesktopMcpRuntimeState _state;
  Process? _process;
  StreamSubscription<String>? _stdoutSubscription;
  StreamSubscription<String>? _stderrSubscription;
  Future<void>? _startFuture;
  Timer? _healthTimer;
  Timer? _restartTimer;
  bool _healthCheckInFlight = false;
  bool _manualStop = false;
  int _restartAttempts = 0;

  DesktopMcpRuntimeState get state => _state;
  String get baseUrl => _composeBaseUrl(_host, _port);
  Stream<DesktopMcpRuntimeState> get states => _stateController.stream;

  Future<void> ensureStarted() {
    if (!AppPlatform.isDesktop) {
      return Future.value();
    }

    final inFlight = _startFuture;
    if (inFlight != null) {
      return inFlight;
    }

    if (_state.status == DesktopMcpRuntimeStatus.ready) {
      return Future.value();
    }

    _startFuture = _ensureStartedInternal().whenComplete(() {
      _startFuture = null;
    });
    return _startFuture!;
  }

  Future<void> stop() async {
    _stopHealthMonitoring();
    _restartTimer?.cancel();
    _restartTimer = null;
    _restartAttempts = 0;

    if (_process == null) {
      _setState(
        DesktopMcpRuntimeState.stopped(
          baseUrl: baseUrl,
          detail: 'Desktop MCP runtime stopped.',
        ),
      );
      return;
    }

    _manualStop = true;
    final process = _process;
    process?.kill();
    if (process != null) {
      try {
        await process.exitCode.timeout(const Duration(seconds: 2));
      } on TimeoutException {
        LoggerService.warning(
          'DesktopMcpRuntimeController: Timed out waiting for runtime shutdown',
        );
      }
    }
  }

  Future<void> dispose() async {
    unawaited(stop());
    _http.close();
    await _stateController.close();
  }

  Future<void> _ensureStartedInternal() async {
    if (await _isHealthy()) {
      _restartAttempts = 0;
      _setState(
        DesktopMcpRuntimeState.ready(
          baseUrl: baseUrl,
          detail: 'Using existing MCP runtime at $baseUrl.',
        ),
      );
      _startHealthMonitoring();
      return;
    }

    _stopHealthMonitoring();
    final config = await _resolveLaunchConfig();
    await _killExistingProcess();

    _setState(
      DesktopMcpRuntimeState.starting(
        baseUrl: baseUrl,
        detail: 'Launching local Node MCP runtime…',
      ),
    );

    LoggerService.info(
      'DesktopMcpRuntimeController: Starting Node runtime from ${config.runnerPath}',
    );

    try {
      _manualStop = false;
      final process = await Process.start(
        config.nodeBinary,
        [config.runnerPath],
        workingDirectory: config.workDirectory,
        environment: {
          ...Platform.environment,
          'MCP_MANAGER_HOST': _host,
          'MCP_MANAGER_PORT': _port.toString(),
          if (config.registryUrl != null)
            'MCP_REGISTRY_URL': config.registryUrl!,
          if (config.registryCachePath != null)
            'MCP_REGISTRY_CACHE_PATH': config.registryCachePath!,
          if (config.registryPath != null)
            'MCP_REGISTRY_PATH': config.registryPath!,
        },
      );

      _process = process;
      _bindProcessLogs(process);
      _watchProcessExit(process);

      await _waitUntilHealthy();
      _restartAttempts = 0;
      _setState(
        DesktopMcpRuntimeState.ready(
          baseUrl: baseUrl,
          detail: 'Local MCP runtime is healthy at $baseUrl.',
        ),
      );
      _startHealthMonitoring();
    } catch (error, stackTrace) {
      _stopHealthMonitoring();
      LoggerService.error(
        'DesktopMcpRuntimeController: Failed to start local MCP runtime',
        error,
        stackTrace,
      );
      _setState(
        DesktopMcpRuntimeState.failed(
          baseUrl: baseUrl,
          detail: error.toString(),
        ),
      );
      await _killExistingProcess();
      _scheduleRestart('Startup failed. Retrying automatically…');
    }
  }

  void _bindProcessLogs(Process process) {
    _stdoutSubscription?.cancel();
    _stderrSubscription?.cancel();

    _stdoutSubscription = process.stdout
        .transform(utf8.decoder)
        .transform(const LineSplitter())
        .listen((line) {
          LoggerService.info('DesktopMcpRuntime stdout: $line');
        });

    _stderrSubscription = process.stderr
        .transform(utf8.decoder)
        .transform(const LineSplitter())
        .listen((line) {
          LoggerService.warning('DesktopMcpRuntime stderr: $line');
        });
  }

  void _watchProcessExit(Process process) {
    unawaited(() async {
      final exitCode = await process.exitCode;
      if (!identical(_process, process)) {
        return;
      }

      await _stdoutSubscription?.cancel();
      await _stderrSubscription?.cancel();
      _stdoutSubscription = null;
      _stderrSubscription = null;
      _process = null;
      _stopHealthMonitoring();

      if (_manualStop) {
        _manualStop = false;
        _setState(
          DesktopMcpRuntimeState.stopped(
            baseUrl: baseUrl,
            detail: 'Desktop MCP runtime stopped.',
          ),
        );
        return;
      }

      final detail = 'Local MCP runtime exited with code $exitCode.';
      LoggerService.warning('DesktopMcpRuntimeController: $detail');
      _setState(
        DesktopMcpRuntimeState.failed(
          baseUrl: baseUrl,
          detail: detail,
          lastExitCode: exitCode,
        ),
      );
      _scheduleRestart('Runtime exited unexpectedly. Restarting…');
    }());
  }

  Future<void> _waitUntilHealthy() async {
    final startedAt = DateTime.now();
    while (DateTime.now().difference(startedAt) < _healthTimeout) {
      if (await _isHealthy()) {
        return;
      }
      if (_process == null) {
        throw StateError('Local MCP runtime exited before becoming healthy.');
      }
      await Future.delayed(const Duration(milliseconds: 400));
    }

    throw TimeoutException(
      'Timed out waiting for local MCP runtime health at $baseUrl/health',
      _healthTimeout,
    );
  }

  Future<bool> _isHealthy() async {
    try {
      final response = await _http
          .get(Uri.parse('$baseUrl/health'))
          .timeout(const Duration(seconds: 2));
      return response.statusCode >= 200 && response.statusCode < 300;
    } catch (_) {
      return false;
    }
  }

  void _startHealthMonitoring() {
    _stopHealthMonitoring();
    _healthTimer = Timer.periodic(_healthCheckInterval, (_) {
      unawaited(_checkRuntimeHealth());
    });
  }

  void _stopHealthMonitoring() {
    _healthTimer?.cancel();
    _healthTimer = null;
  }

  Future<void> _checkRuntimeHealth() async {
    if (_healthCheckInFlight ||
        _healthTimer == null ||
        _state.status != DesktopMcpRuntimeStatus.ready) {
      return;
    }

    _healthCheckInFlight = true;
    final healthy = await _isHealthy();
    _healthCheckInFlight = false;

    if (healthy ||
        _healthTimer == null ||
        _state.status != DesktopMcpRuntimeStatus.ready) {
      return;
    }

    _stopHealthMonitoring();
    const detail = 'Local MCP runtime health check failed.';
    LoggerService.warning('DesktopMcpRuntimeController: $detail');
    _setState(DesktopMcpRuntimeState.failed(baseUrl: baseUrl, detail: detail));
    _scheduleRestart('Runtime became unhealthy. Restarting…');
  }

  void _scheduleRestart(String detail) {
    if (!AppPlatform.isDesktop || _restartTimer != null || _manualStop) {
      return;
    }

    _stopHealthMonitoring();
    if (_restartAttempts >= _maxAutomaticRestartAttempts) {
      final lastFailure = _state.detail;
      final terminalDetail =
          'The MCP runtime failed after $_maxAutomaticRestartAttempts '
          'automatic restart attempts.'
          '${lastFailure == null ? '' : '\n\n$lastFailure'}';
      LoggerService.error(
        'DesktopMcpRuntimeController: Automatic restart limit reached',
        terminalDetail,
      );
      _setState(
        DesktopMcpRuntimeState.failed(
          baseUrl: baseUrl,
          detail: terminalDetail,
          lastExitCode: _state.lastExitCode,
          automaticRetriesExhausted: true,
        ),
      );
      return;
    }

    _restartAttempts += 1;
    final multiplier = _restartAttempts.clamp(1, _maxAutomaticRestartAttempts);
    final delay = Duration(seconds: _restartBaseDelay.inSeconds * multiplier);

    _setState(
      DesktopMcpRuntimeState.restarting(
        baseUrl: baseUrl,
        detail: '$detail Next attempt in ${delay.inSeconds}s.',
      ),
    );

    _restartTimer = Timer(delay, () {
      _restartTimer = null;
      unawaited(ensureStarted());
    });
  }

  Future<void> _killExistingProcess() async {
    final process = _process;
    if (process == null) {
      return;
    }

    _process = null;
    process.kill();
    try {
      await process.exitCode.timeout(const Duration(seconds: 2));
    } on TimeoutException {
      LoggerService.warning(
        'DesktopMcpRuntimeController: Timed out waiting for old runtime process to exit',
      );
    }

    await _stdoutSubscription?.cancel();
    await _stderrSubscription?.cancel();
    _stdoutSubscription = null;
    _stderrSubscription = null;
  }

  Future<_DesktopMcpLaunchConfig> _resolveLaunchConfig() async {
    final nodeBinary = _readNodeBinary();
    final repoRoot = await _resolveRuntimeRepoRoot();
    final runnerPath = _readRunnerPath(repoRoot.path);
    final registryUrl = _readRegistryUrl();
    final registryPath = registryUrl == null
        ? _readRegistryPath(repoRoot.path)
        : null;
    final registryCachePath = registryUrl == null
        ? null
        : _readRegistryCachePath(repoRoot.path);

    final runnerFile = File(runnerPath);

    if (!await runnerFile.exists()) {
      throw StateError(
        'MCP runtime runner not found at $runnerPath. '
        'Set MCP_RUNTIME_RUNNER_PATH to override.',
      );
    }

    if (registryPath != null && !await File(registryPath).exists()) {
      throw StateError(
        'MCP runtime registry not found at $registryPath. '
        'Set MCP_RUNTIME_REGISTRY_PATH to override.',
      );
    }

    return _DesktopMcpLaunchConfig(
      nodeBinary: nodeBinary,
      workDirectory: repoRoot.path,
      runnerPath: runnerFile.path,
      registryPath: registryPath,
      registryUrl: registryUrl,
      registryCachePath: registryCachePath,
    );
  }

  Future<Directory> _resolveRuntimeRepoRoot() async {
    final override = dotenv.maybeGet('MCP_RUNTIME_WORKDIR');
    if (override != null && override.trim().isNotEmpty) {
      final directory = Directory(override.trim());
      if (await directory.exists()) {
        return directory;
      }
    }

    final current = Directory.current.path;
    final candidates = <Directory>[
      Directory('$current/../synapse-mcp-plane'),
      Directory('$current/synapse-mcp-plane'),
    ];

    for (final candidate in candidates) {
      if (await candidate.exists()) {
        return candidate;
      }
    }

    throw StateError(
      'Unable to locate the synapse-mcp-plane repo. '
      'Set MCP_RUNTIME_WORKDIR in .env to point to it.',
    );
  }

  void _setState(DesktopMcpRuntimeState nextState) {
    _state = nextState;
    if (!_stateController.isClosed) {
      _stateController.add(nextState);
    }
  }

  static String _readHost() {
    final override = dotenv.maybeGet('MCP_MANAGER_HOST');
    return (override == null || override.trim().isEmpty)
        ? '127.0.0.1' //for debug
        : override.trim();
  }

  static int _readPort() {
    final override = dotenv.maybeGet('MCP_MANAGER_PORT');
    return int.tryParse(override ?? '') ?? 4777;
  }

  static String _readNodeBinary() {
    final override = dotenv.maybeGet('MCP_RUNTIME_NODE_BINARY');
    return (override == null || override.trim().isEmpty)
        ? 'node'
        : override.trim();
  }

  static String _readRunnerPath(String repoRoot) {
    final override = dotenv.maybeGet('MCP_RUNTIME_RUNNER_PATH');
    if (override != null && override.trim().isNotEmpty) {
      return override.trim();
    }
    return '$repoRoot/dev/desktop-runtime-runner.mjs';
  }

  static String _readRegistryPath(String repoRoot) {
    final override = dotenv.maybeGet('MCP_RUNTIME_REGISTRY_PATH');
    if (override != null && override.trim().isNotEmpty) {
      return override.trim();
    }
    return '$repoRoot/dev/registry.desktop.json';
  }

  static String? _readRegistryUrl() {
    final override = dotenv.maybeGet('MCP_RUNTIME_REGISTRY_URL');
    if (override == null || override.trim().isEmpty) return null;
    return override.trim();
  }

  static String _readRegistryCachePath(String repoRoot) {
    final override = dotenv.maybeGet('MCP_RUNTIME_REGISTRY_CACHE_PATH');
    if (override != null && override.trim().isNotEmpty) {
      return override.trim();
    }
    return '$repoRoot/.cache/mcp-registry.json';
  }

  static String _composeBaseUrl(String host, int port) {
    return 'http://$host:$port';
  }
}

