import 'package:drift/drift.dart';

/// SQLite table for storing installed plugin metadata.
/// 
/// This table stores all manifest data from installed plugins,
/// enabling fast queries for LLM prompts and background isolate access.
class InstalledPluginsTable extends Table {
  /// Plugin ID (e.g., "com.synapse.google.keep") - Primary key
  TextColumn get id => text()();

  /// Plugin display name
  TextColumn get name => text()();

  /// Plugin version (semver)
  TextColumn get version => text()();

  /// Plugin description
  TextColumn get description => text().withDefault(const Constant(''))();

  /// Plugin author
  TextColumn get author => text().withDefault(const Constant(''))();

  /// Icon identifier (from manifest)
  TextColumn get icon => text().nullable()();

  /// Triggers as JSON array (e.g., '["notes", "keep", "reminder"]')
  TextColumn get triggersJson => text().withDefault(const Constant('[]'))();

  /// Input schema as JSON object (for LLM payload validation)
  TextColumn get inputSchemaJson => text().withDefault(const Constant('{}'))();

  /// Security config as JSON object
  TextColumn get securityJson => text().withDefault(const Constant('{}'))();

  /// Auth config as JSON object (OAuth providers, scopes)
  TextColumn get authJson => text().nullable()();

  /// Path to plugin.js file for execution
  TextColumn get scriptPath => text()();

  /// Whether the plugin is enabled by user
  BoolColumn get isEnabled => boolean().withDefault(const Constant(true))();

  /// When the plugin was installed
  DateTimeColumn get installedAt => dateTime()();

  /// When the plugin was last executed
  DateTimeColumn get lastUsedAt => dateTime().nullable()();

  @override
  Set<Column> get primaryKey => {id};
}

