/// OAuth2 provider configuration.
///
/// Defines the endpoints and credentials needed for OAuth2 authentication.
class OAuth2Provider {
  /// Provider identifier (e.g., 'google', 'microsoft', 'github')
  final String name;

  /// OAuth2 client ID
  final String clientId;

  /// OAuth2 client secret (null for PKCE flow, which is recommended)
  final String? clientSecret;

