  // ===========================================================================
  // Shortcuts (iOS/macOS)
  // ===========================================================================

  /// Run an iOS Shortcut by name
  /// 
  /// Uses the `shortcuts://run-shortcut?name=NAME&input=INPUT` scheme.
  Future<void> runShortcut(String name, String? input) async {
    if (!Platform.isIOS && !Platform.isMacOS) {
      LoggerService.warning('SystemBridge: shortcuts:// only supported on iOS/macOS');
      return;
    }

    final uri = Uri(
      scheme: 'shortcuts',
      host: 'run-shortcut',
      queryParameters: {
        'name': name,
        if (input != null) 'input': input,
      },
    );

    try {
      LoggerService.info('SystemBridge: Launching shortcut $name');
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    } catch (e) {
      LoggerService.error('SystemBridge: Failed to launch shortcut', e);
      rethrow;
    }
  }

